window.EXTRA = {"neuro":{"learn":[{"h":"הרצונית והבלתי רצונית","steps":false,"items":["מערכת העצבים ההיקפית (PNS) מתחלקת לרצונית (סומטית, SNS) ולבלתי רצונית (אוטונומית, ANS).","הרצונית אחראית על התנועות שאנחנו בוחרים לעשות בשרירי השלד.","האוטונומית מפעילה תהליכים אוטומטיים: דופק, נשימה, עיכול, הזעה.","האוטונומית מתחלקת לסימפתטית ולפרסימפתטית. שתיהן משפיעות על אותם איברים, וכל פעם אחת דומיננטית לפי המצב."]},{"h":"סוגי נוירונים","steps":false,"items":["נוירון תחושתי (Sensory) מעביר מידע מהקולטנים אל מערכת העצבים המרכזית.","נוירון תנועתי (Motor) מעביר פקודה מהמרכזית אל השריר או האיבר.","נוירון מקשר (Association) מחבר בין נוירון תחושתי לנוירון תנועתי.","חלקי הנוירון: דנדריטים קולטים את הגירוי, גוף התא עם הגרעין, אקסון ארוך שמעביר את הדחף, ומעטפת מיאלין שמאיצה אותו."]},{"h":"מה קורה בסינפסה","steps":true,"items":["דחף חשמלי מגיע לקצה האקסון.","הנוירון משחרר נוירוטרנסמיטר (חומר כימי) למרווח הסינפטי.","הנוירוטרנסמיטר נקשר לקולטנים בתא הבא ויוצר בו דחף חדש.","הנוירוטרנסמיטר נשאב חזרה לנוירון ששחרר אותו."]}],"quiz":[["איזו מערכת אחראית על תנועות רצוניות של שרירי השלד?",["המערכת הסומטית (הרצונית)","המערכת הסימפתטית","המערכת הפרסימפתטית","גזע המוח בלבד"],"מערכת העצבים הרצונית (SNS) שולטת בתגובות הרצוניות של השרירים."],["מה יגרום גירוי של עצב הוואגוס?",["הפעלה של המערכת הפרסימפתטית, למשל האטת דופק","האצת דופק","הרחבת אישונים","עלייה בלחץ הדם"],"הוואגוס הוא העצב העיקרי של המערכת הפרסימפתטית; גירוי שלו מאט את הלב."],["מה תפקידו של נוירון מקשר?",["לחבר בין נוירון תחושתי לנוירון תנועתי","להעביר פקודה לשריר","לקלוט גירוי מהעור","לייצר מיאלין"],"נוירון מקשר (Association neuron) נמצא בין התחושתי לתנועתי."],["באיזה חלק של הנוירון נקלט הגירוי מהתא הקודם?",["בדנדריטים","באקסון","במעטפת המיאלין","בגרעין"],"הדנדריטים הם הסיבים המתפצלים שקולטים את הגירוי."],["מה קורה לדחף החשמלי במרווח הסינפטי?",["הוא מתורגם לדחף כימי (נוירוטרנסמיטר)","הוא נעצר לגמרי","הוא מתחזק בזכות המיאלין","הוא עובר דרך הדם"],"בסינפסה הדחף החשמלי הופך לשחרור של חומר כימי שמגרה את התא הבא."],["איזו אונה של המוח נמצאת בחלק האחורי ואחראית בעיקר על הראייה?",["האונה העורפית","האונה המצחית","האונה הרקתית","האונה הקודקודית"],"האונה העורפית (Occipital) מעבדת את הראייה."],["כמה זוגות עצבים יוצאים מהגולגולת?",["12","31","8","24"],"12 זוגות עצבי גולגולת; 31 זוגות יוצאים מחוט השדרה."]],"images":[["neuro--1-3-p-003-015.webp","מערכת העצבים בראש ובצוואר"],["neuro--1-3-p-005-023.webp","מערכת העצבים המרכזית: המוח וחוט השדרה"],["neuro--1-3-p-005-025.webp","מערכת העצבים ההיקפית"],["neuro--1-3-p-010-045.webp","חתך של המוח בתוך הגולגולת"],["neuro--1-3-p-015-073.webp","המערכת האוטונומית והאיברים שהיא מעצבבת"],["neuro--1-3-p-020-088.webp","מסלול הגירוי: קולטן, נוירון תחושתי, נוירון מקשר, נוירון תנועתי"],["neuro--1-3-p-023-103.webp","מבנה הנוירון: דנדריטים, גוף התא, אקסון ומיאלין"],["neuro--1-3-p-022-094.webp","סינפסה: שחרור הנוירוטרנסמיטר לקולטנים"]]},"resp":{"learn":[{"h":"איך נכנס האוויר (מכניקת הנשימה)","steps":true,"items":["השאיפה היא תהליך פעיל: הסרעפת מתכווצת ויורדת כלפי מטה.","השרירים הבין-צלעיים מתכווצים ומרימים את הצלעות כלפי מעלה והחוצה, כמו ידית של דלי.","בית החזה גדל, והריאות מתרחבות יחד איתו בזכות קרום הפלאורה הכפול.","הלחץ בתוך הריאות יורד מתחת ללחץ האוויר בחוץ, והאוויר נכנס.","הנשיפה בדרך כלל סבילה: השרירים נרפים, בית החזה קטן והאוויר יוצא."]},{"h":"הסימפונות","steps":false,"items":["הקנה מתפצל לסימפון ימני ולסימפון שמאלי.","הסימפון הימני מתחלק לשלושה, אחד לכל אונה של הריאה הימנית.","הסימפון השמאלי מתחלק לשניים, אחד לכל אונה של הריאה השמאלית.","הסימפונות ממשיכים להתפצל עד הנאדיות (אלוואולי), שעטופות ברשת נימים."]},{"h":"הדרך של החמצן","steps":false,"items":["בנאדית: החמצן עובר לנים, והפחמן הדו-חמצני עובר מהנים לנאדית (דיפוזיה).","הדם העשיר בחמצן חוזר דרך ורידי הריאה אל הלב.","מהלב הוא נשלח לכל תאי הגוף, וההמוגלובין מוסר את החמצן לתאים (פרפוזיה).","בגלל זה צריך גם נשימה תקינה וגם זרימת דם תקינה כדי שהתאים יקבלו חמצן."]}],"quiz":[["מה קורה לסרעפת בזמן שאיפה?",["מתכווצת ויורדת כלפי מטה","נרפית ועולה","לא זזה","נלחצת אל הלב"],"התכווצות הסרעפת מגדילה את נפח בית החזה ומאפשרת לאוויר להיכנס."],["למה נכנס אוויר לריאות בשאיפה?",["כי הלחץ בתוך הריאות יורד מתחת ללחץ בחוץ","כי הריאות מתכווצות","כי הלב דוחף אוויר","כי האפיגלוטיס נפתחת"],"בית החזה גדל, נוצר תת-לחץ והאוויר זורם פנימה."],["לכמה חלקים מתחלק הסימפון הימני הראשי?",["שלושה","שניים","ארבעה","אחד"],"שלושה, אחד לכל אונה של הריאה הימנית."],["אילו שרירים מסייעים לשאיפה מלבד הסרעפת?",["השרירים הבין-צלעיים","שרירי הבטן בלבד","שרירי הגב התחתון","שרירי הירך"],"הבין-צלעיים מרימים את הצלעות ומרחיבים את בית החזה."],["לאן חוזר הדם העשיר בחמצן מהריאות?",["דרך ורידי הריאה לעלייה השמאלית","דרך עורק הריאה לחדר הימני","דרך הוורידים הנבובים לעלייה הימנית","ישר לאאורטה"],"ורידי הריאה מביאים דם מחומצן לעלייה השמאלית."],["מהו קרום הפלאורה?",["קרום כפול שעוטף את הריאות ומצמיד אותן לדופן בית החזה","שריר שמכווץ את הריאה","מכסה מעל הקנה","שכבת הסחוס של הסימפונות"],"בזכות הפלאורה הריאה מתרחבת יחד עם בית החזה."],["בשני סוגי הנשימה, מהי הנשימה התאית?",["הגעת החמצן לתאים ויציאת CO2 מהם לדם","הכנסת אוויר לריאות","סגירת האפיגלוטיס","השיעול"],"נשימה ריאתית מכניסה חמצן לריאות; נשימה תאית מעבירה אותו לתאים."]],"images":[["resp--1-4-p-003-013.webp","מערכת הנשימה: דרכי האוויר העליונות והתחתונות"],["resp--1-4-p-006-025.webp","חתך של הפה, הלוע, האפיגלוטיס והקנה"],["resp--1-4-p-008-033.webp","קנה הנשימה וההתפצלות לסימפונות"],["resp--1-4-p-011-043.webp","הנאדית: חמצן נכנס לנים ו-CO2 יוצא"],["resp--1-4-p-012-046.webp","דיפוזיה בין הנאדית לכדוריות הדם"],["resp--1-4-p-013-050.webp","שאיפה: הסרעפת יורדת ובית החזה מתרחב"]]},"cardio":{"learn":[{"h":"שלוש שכבות של עורק","steps":false,"items":["פנימית: שכבת תאי אנדותל חלקה.","אמצעית: שריר חלק ורקמה גמישה, עבה במיוחד בעורקים.","חיצונית: רקמת חיבור.","לווריד אותן שכבות, אבל השכבה האמצעית דקה יותר, ויש לו מסתמים שמונעים זרימה לאחור."]},{"h":"תפקידי הדם","steps":false,"items":["הובלת חמצן וחומרי מזון אל התאים.","פינוי פסולת ו-CO2 מהתאים.","הגנה על הגוף (תאי דם לבנים ונוגדנים).","שמירה על איזון פנימי (הומיאוסטזיס)."]},{"h":"מרכיבי הדם בפירוט","steps":false,"items":["פלסמה (כ-55%): מים, חלבונים, פקטורי קרישה, נוגדנים ואלקטרוליטים.","תאים לבנים: יכולים לצאת מכלי הדם, לנוע ולשנות צורה. עלייה בכמותם מעידה על דלקת.","טסיות: אחראיות לקרישה, חיות 7-10 ימים.","תאים אדומים: נושאים המוגלובין ונותנים לדם את צבעו.","דם צמיגי מדי (למשל בהתייבשות) עלול לסתום כלי דם; דם דליל מדי פוגע באספקת החמצן."]},{"h":"ההולכה החשמלית בקצרה","steps":true,"items":["ה-SA Node בעלייה הימנית יוצר את הקצב: 60-100 בדקה.","האות עובר בעליות ומכווץ אותן.","ה-AV Node מעכב את האות מעט, כדי שהחדרים יתמלאו.","האות ממשיך לחדרים, והם מתכווצים ושולחים דם לגוף ולריאות."]}],"quiz":[["מה קצב הלב התקין שקובע ה-SA Node?",["60-100 בדקה","40-60 בדקה","100-140 בדקה","20-40 בדקה"],"ה-SA Node הוא הקוצב הטבעי ובאופן תקין קובע 60-100 פעימות בדקה."],["מה תפקיד העיכוב ב-AV Node?",["לאפשר לחדרים להתמלא בדם לפני ההתכווצות","להאיץ את הדופק","לעצור את הלב","לכווץ את העליות"],"העיכוב הקל נותן לעליות זמן להעביר את הדם לחדרים."],["כמה עורקים כליליים (קורונריים) מרכזיים יש?",["שלושה","אחד","חמישה","שניים"],"שלושה עורקים קורונריים מרכזיים מספקים דם לשריר הלב."],["מה מונע זרימה לאחור בוורידים?",["מסתמים ורידיים","שכבת שריר עבה","הלחץ הגבוה בהם","הטסיות"],"לוורידים יש מסתמים, כי הלחץ בהם נמוך."],["מה מעידה עלייה ברמת התאים הלבנים?",["תהליך דלקתי או זיהום","התייבשות","דימום","חוסר חמצן"],"הלויקוציטים הם חלק ממערכת החיסון ועולים בזמן דלקת."],["מה מעניק לדם את צבעו האדום?",["ההמוגלובין שבתאים האדומים","הפלסמה","הטסיות","האלקטרוליטים"],"התאים האדומים נושאים המוגלובין, והוא נותן את הצבע."],["מה אורך החיים של טסית?",["7-10 ימים","120 ימים","יום אחד","שנה"],"טסיות חיות כשבוע עד עשרה ימים."],["איזה מחזור דם מתחיל בחדר הימני ומסתיים בעלייה השמאלית?",["המחזור הקטן (הריאתי)","המחזור הגדול","המחזור הכלילי","מחזור הנימים"],"חדר ימין, עורק הריאה, הריאות, ורידי הריאה, עלייה שמאל."]],"images":[["cardio--1-5-p-004-019.webp","מבנה הלב: עליות, חדרים וכלי הדם הגדולים"],["cardio--1-5-p-007-031.webp","ארבעת המסתמים: מיטרלי, טריקוספידלי, אאורטלי ופולמונרי"],["cardio--1-5-p-012-049.webp","המחזור הקטן (ריאתי) והמחזור הגדול (סיסטמי)"],["cardio--1-5-p-015-060.webp","העורקים הכליליים שמזינים את שריר הלב"],["cardio--1-5-p-017-068.webp","מערכת ההולכה החשמלית בלב"],["cardio--1-5-p-019-076.webp","עורק, נימים ווריד"],["cardio--1-5-p-020-079.webp","שכבות דופן העורק"],["cardio--1-5-p-021-085.webp","מסתמים בווריד: פתוח וסגור"],["cardio--1-5-p-024-095.webp","מרכיבי הדם: פלסמה ותאים"],["cardio--1-5-p-026-103.webp","טסיות (תרומבוציטים)"],["cardio--1-5-p-027-107.webp","כדוריות דם אדומות"]]},"adult-cpr":{"learn":[{"h":"לפני שנוגעים: בטיחות והכרה","steps":true,"items":["בטיחות אישית ובטיחות הזירה, לפני הכול.","בדיקת הכרה לפי AVPU: Alert ער, Verbal מגיב לקול, Pain מגיב לכאב, Unresponsive לא מגיב.","חשיפת בית החזה והתרשמות מנשימה לפחות 5 שניות (ולא יותר מ-10), יחד עם בדיקת דופק בעורק ראשי.","אין נשימה ואין דופק בוודאות: מתחילים מיד עיסויים ומדווחים מיקום."]},{"h":"למה כל דקה חשובה","steps":false,"items":["זמן ההגעה הממוצע של אמבולנס הוא כ-9 דקות.","בלי עיסויים והנשמות עד אז, גם צוות ALS כמעט תמיד יגיע מאוחר מדי.","המוח הוא האיבר הרגיש ביותר בגוף: אחרי 6-10 דקות בלי חמצן נגרם בו נזק.","החייאה טובה 'קונה זמן' עד השוק וההחייאה המתקדמת."]},{"h":"פתיחת נתיב אוויר בפועל","steps":true,"items":["מסתכלים לתוך הפה ומוודאים שהוא נקי.","אם יש הפרשות: מטים את המטופל על הצד ומוציאים אותן החוצה.","מטים את הראש לאחור ומרימים את הסנטר, כדי שבסיס הלשון לא יחסום את הקנה.","מנשימים דרך מסכת כיס שקופה, כדי לראות הפרשות בזמן ההנשמה."]}],"quiz":[["מה המשמעות של P בסולם AVPU?",["מגיב לכאב","מגיב לקול","ער ומתמצא","לא מגיב"],"A ער, V מגיב לקול, P מגיב לכאב, U לא מגיב."],["מה הפעולה הראשונה כשמגיעים לאדם שקרס?",["לוודא בטיחות אישית ובטיחות הזירה","להתחיל מיד עיסויים","לבדוק דופק","לחפש דפיברילטור"],"לפני הכול בטיחות, אחרת אנחנו עלולים להפוך לנפגע נוסף."],["מה זמן ההגעה הממוצע של אמבולנס, לפי המצגת?",["כ-9 דקות","כדקה","כ-30 דקות","כ-20 דקות"],"לכן ההחייאה של הנוכחים במקום קריטית."],["למה המסכה להנשמה שקופה?",["כדי לראות הפרשות או הקאה בזמן ההנשמה","כדי שתהיה זולה","כדי לראות את צבע העור","אין סיבה מיוחדת"],"אם רואים הפרשות עוצרים, מטים על הצד ומנקים."],["יש הפרשות בפה של מטופל בדום לב. מה עושים?",["מטים אותו על הצד ומוציאים את ההפרשות החוצה","מנשימים חזק יותר","ממשיכים לעסות בלי להנשים","מטים את הראש קדימה"],"קודם מנקים, אחר כך פותחים נתיב אוויר ומנשימים."],["מה גורם לחסימת נתיב האוויר אצל אדם מחוסר הכרה?",["צניחת בסיס הלשון בגלל רפיון שרירים","התכווצות הסרעפת","בצקת בריאות","דופק מהיר"],"בלי טונוס שרירים הלשון נופלת אחורה וחוסמת את הקנה."],["מה עלול לקרות לתוכן הקיבה אצל מחוסר הכרה?",["לעלות לפה בגלל רפיון שער הקיבה","להיעלם","להיספג בדם","לחסום את הוושט בלבד"],"רפיון השרירים פותח את שער הקיבה, ולכן יש סכנת שאיפה."]],"images":[["adult-cpr--1-7-p-009-041.webp","בדיקת דופק בעורק הצוואר (קרוטיד)"],["adult-cpr--1-7-p-011-047.webp","סדר הפעולות: C עיסויים, A נתיב אוויר, B הנשמות"],["adult-cpr--1-7-p-012-052.webp","עיסויי חזה: ידיים במרכז בית החזה, ידיים ישרות"],["adult-cpr--1-7-p-013-058.webp","מחוסר הכרה: בסיס הלשון צונח וחוסם את הקנה"],["adult-cpr--1-7-p-013-060.webp","הטיית ראש לאחור פותחת את נתיב האוויר"],["adult-cpr--1-7-p-014-065.webp","מסכת כיס להנשמה"]]},"aed":{"learn":[{"h":"קצת היסטוריה ונתונים","steps":false,"items":["דפיברילציה הוזכרה לראשונה ב-1899, אב-טיפוס הופיע ב-1930, ושוק ראשון לאדם ניתן ב-1947 והציל ילד בן 14.","בישראל יש דום לב כמעט 1,000 פעמים בשבוע, בעיקר בגברים מעל 30 ונשים מעל 45.","כ-5,000 איש מתים בישראל כל שנה מ-VF (פרפור חדרים).","רוב המכשירים בישראל חצי-אוטומטיים: הם ממליצים על שוק, אבל אנחנו לוחצים."]},{"h":"איפה חייב להיות מכשיר (לפי החוק)","steps":false,"items":["קניונים, תחנות מרכזיות, ומקומות עבודה עם 500 עובדים ומעלה.","אצטדיונים עם 500 מושבים ומעלה, ומכוני כושר עם 500 מתאמנים קבועים ומעלה.","בתי אבות ודיור מוגן, בתי סוהר ובתי מעצר.","בתי מלון עם 250 חדרים ומעלה, חופים מוכרזים ובריכות ציבוריות.","אוניות ומטוסים ל-100 נוסעים ומעלה, אולמות אירועים ל-500 איש ומעלה.","במקומות האלה יש שילוט שמכוון למכשיר, ויש אפליקציה שמראה את המכשיר הקרוב."]},{"h":"תמצית הפעלה","steps":true,"items":["מדווחים למוקד ומתחילים עיסויים.","מפעילים את המכשיר ומחברים מדבקות לפי הסימון; בן הזוג ממשיך לעסות בזמן ההדבקה.","לא נוגעים במטופל בזמן האנליזה.","אם מומלץ שוק: מכריזים בקול, מוודאים שאף אחד לא נוגע, ולוחצים.","ממשיכים 2 דקות החייאה ומקשיבים למכשיר."]}],"quiz":[["כמה מקרי דום לב יש בישראל בערך כל שבוע, לפי המצגת?",["כ-1,000","כ-10","כ-100","כ-10,000"],"קרוב ל-1,000 בשבוע, בעיקר במבוגרים."],["מה ההבדל בין מכשיר אוטומטי לחצי-אוטומטי?",["החצי-אוטומטי ממליץ על שוק ואנחנו לוחצים; האוטומטי נותן לבד","אין הבדל","החצי-אוטומטי לא מאבחן","האוטומטי מתאים רק לילדים"],"רוב המכשירים בארץ חצי-אוטומטיים."],["באיזה בית מלון החוק מחייב דפיברילטור?",["במלון עם 250 חדרים ומעלה","בכל מלון","רק במלון עם בריכה","במלון עם 50 חדרים ומעלה"],"לפי חוק הצבת מכשירי החייאה, מ-250 חדרי אירוח."],["בן הזוג מדביק מדבקות. מה אתה עושה בינתיים?",["ממשיך לעסות","עוצר הכול ומחכה","בודק דופק","מנשים בלבד"],"מצמצמים הפסקות בעיסויים ככל האפשר."],["המטופל רטוב מגשם. מה עושים לפני ההדבקה?",["מייבשים היטב את בית החזה","לא משתמשים במכשיר","מדביקים על הבגד","מחכים שיתייבש לבד"],"מייבשים את החזה, ובמים עומדים מרחיקים את המטופל קודם."],["באיזו שנה ניתן שוק חשמלי ראשון לאדם כטיפול, לפי המצגת?",["1947","1899","1930","2008"],"ב-1947 שוק הציל ילד בן 14 בניתוח."]],"images":[["aed--1-7-p-028-119.webp","סיכויי ההישרדות יורדים עם כל דקה עד השוק"],["aed--1-7-p-021-088.webp","ארון דפיברילטור ציבורי"],["aed--1-7-p-032-134.webp","דפיברילטור חצי-אוטומטי"],["aed--1-7-p-039-189.webp","מדבקות מבוגר ומדבקות ילד"],["aed--1-7-p-040-195.webp","מיקום המדבקות כפי שמופיע על האריזה"],["aed--1-7-p-041-202.webp","מדבקות בילד: אחת על החזה ואחת על הגב"]]},"lifeline":{"learn":[],"quiz":[],"images":[]},"team-cpr":{"learn":[{"h":"חלקי האמבו","steps":false,"items":["מפוח (שקית ההנשמה) עם שסתום פורק לחץ.","מסכה בגודל שמתאים לפני המטופל.","מסנן ויראלי בין המסכה למפוח.","צינורית חמצן ושקית העשרה, שמעלות את ריכוז החמצן בהנשמה.","אטימות טובה: אחיזת C-E ומסכה מנופחת כראוי."]},{"h":"חישוב זמן חמצן במיכל","steps":true,"items":["מחלקים את הלחץ בשעון (PSI) ב-15 ומקבלים אטמוספרות.","כופלים בנפח המיכל: 2.4 ליטר במיכל הנייד, 20 ליטר בנייח.","מחלקים בזרימה לדקה, וזה מספר הדקות שנותרו.","דוגמה: 1,500 PSI = 100 אטמוספרות × 2.4 = 240 ליטר; בזרימה של 10 ליטר לדקה זה 24 דקות."]},{"h":"חלוקת תפקידים","steps":false,"items":["החלפת מעסה כל 2 דקות או קודם אם הוא התעייף, ולא יותר מ-5 שניות להחלפה.","עם AED מתחלפים בזמן שהמכשיר מאבחן.","כשיש 3 מטפלים ומעלה, עדיף שהנשמה באמבו תתבצע בידי שניים: אחד אוטם את המסכה ואחד לוחץ.","החייאת מכשירים דורשת לפחות 2 אנשי צוות."]}],"quiz":[["כמה דקות יספיק מיכל נייד של 2.4 ליטר עם 750 PSI בזרימה של 6 ליטר לדקה?",["20 דקות","10 דקות","40 דקות","5 דקות"],"750÷15 = 50 אטמוספרות, ×2.4 = 120 ליטר, ÷6 = 20 דקות."],["מה מחלקים ב-15 בחישוב החמצן?",["את הלחץ בשעון ב-PSI, כדי לקבל אטמוספרות","את נפח המיכל","את הזרימה","את זמן ההחייאה"],"PSI ÷ 15 ≈ אטמוספרות."],["מה תפקיד שקית ההעשרה באמבו?",["להעלות את ריכוז החמצן בהנשמה","לסנן חיידקים","למדוד נפח","להחליף את המסכה"],"השקית מתמלאת בחמצן מהצינורית, והמפוח שואב ממנה."],["יש 3 מטפלים בהחייאה. איך מנשימים באמבו?",["שני מטפלים: אחד אוטם את המסכה בשתי ידיים ואחד לוחץ על המפוח","מטפל אחד תמיד","לא מנשימים","המעסה מנשים בעצמו"],"הנשמה בשני מטפלים נותנת אטימות טובה יותר."],["מה מינימום אנשי הצוות להחייאת מכשירים?",["2","1","4","5"],"לפחות שני אנשי צוות."],["למה מנתב אוויר קטן מדי מסוכן?",["הוא עלול להפוך לגוף זר בפה ולגרום לחסימה","הוא גורם להקאה","הוא דוחף את הלשון מטה","הוא לא מסוכן"],"מנתב גדול מדי מגרה הקאה ודוחף את הלשון; קטן מדי עלול לחסום."]],"images":[["team-cpr--1-8-p-009-031.webp","מנתבי אוויר בגדלים שונים"],["team-cpr--1-8-p-010-034.webp","מנתב אוויר בתוך הפה: מחזיק את הלשון קדימה"],["team-cpr--1-8-p-012-042.webp","מנתב בגודל מתאים"],["team-cpr--1-8-p-013-047.webp","מנתב גדול מדי"],["team-cpr--1-8-p-017-061.webp","סקשן ידני לשאיבת הפרשות"],["team-cpr--1-8-p-020-074.webp","אמבו: מפוח, מסכה ושקית העשרה"],["team-cpr--1-8-p-019-070.webp","הנשמה באמבו עם אטימת המסכה"],["team-cpr--1-8-p-022-084.webp","אחיזת C-E של המסכה"],["team-cpr--1-8-p-024-091.webp","מיכל חמצן ווסת זרימה"]]},"child-cpr":{"learn":[{"h":"השוואה: מבוגר, ילד, תינוק","steps":false,"items":["קריאה לעזרה: במבוגר מיד; בילד ותינוק בלי טלפון ובלי נוכחים, אחרי 2 דקות החייאה.","עיסויים: מבוגר בשתי ידיים; ילד ביד אחת או שתיים לפי הגודל; תינוק בשתי אצבעות או באגודלים.","דופק מתחת ל-60 עם זילוח לקוי בילד ובתינוק: מתחילים החייאה מיד.","יש דופק ואין נשימה בילד ובתינוק: הנשמה אחת כל 2-3 שניות.","AED: אותו שימוש כמו במבוגר; ההבדל הוא במיקום המדבקות, ובחלק מהמכשירים יש מתג מבוגר/ילד."]}],"quiz":[["ילד בן 5 בדום לב, מטפל יחיד עם טלפון. מתי מזעיקים עזרה?",["מיד, בטלפון על רמקול","אחרי 2 דקות החייאה","אחרי 5 סבבים","רק אחרי שהילד מתעורר"],"אם יש טלפון מזעיקים מיד; רק בלי טלפון ובלי נוכחים מחכים 2 דקות."],["במה מעסים ילד גדול?",["בכרית כף יד אחת או בשתי ידיים, לפי גודלו","בשתי אצבעות","באגודל אחד","באגרוף"],"בוחרים לפי גודל הילד כדי להגיע לעומק הנכון."],["מה מאפשר מתג מבוגר/ילד בחלק מהמכשירים?",["להתאים את עוצמת השוק לילד","לבטל את האנליזה","להחליף שפה","לכבות את המטרונום"],"חלק מה-AED מגיעים עם כפתור כזה במקום מדבקות ילדים."],["ילד עם דופק 50, זילוח לקוי ונשימה לא יעילה. מה עושים?",["מתחילים החייאה מלאה","נותנים חמצן ומחכים","מנשימים בלבד","מעבירים לתנוחת התאוששות"],"דופק מתחת ל-60 עם זילוח לקוי בילד מטופל כמו דום לב."]],"images":[["child-cpr--1-9-p-009-037.webp","מדבקות ילד: על החזה ועל הגב"],["child-cpr--1-9-p-009-038.webp","מיקום מדבקות בילד: מלפנים ומאחור"],["child-cpr--1-9-p-010-046.webp","הנשמה בילד דרך מסכה"]]},"infant-cpr":{"learn":[{"h":"אמבו ומדבקות בתינוק","steps":false,"items":["באמבו לתינוק משתמשים במפוח ובמסכה בגודל תינוק, ולוחצים רק עד שבית החזה עולה.","כשמדביקים בתינוק מדבקה מלפנים ומאחור: האחורית על הגב, מול הקדמית.","בחלק מהמכשירים יש מדבקות ייעודיות לתינוק ולילד."]}],"quiz":[["כמה לוחצים על האמבו בתינוק?",["רק עד שרואים עליית בית חזה","עד הסוף כמו במבוגר","לחיצה חזקה ומהירה","לא משתמשים באמבו בתינוק"],"נפח קטן מספיק; לחיצה חזקה עלולה לפגוע בריאות."],["היכן מדביקים את המדבקה האחורית בתינוק?",["על הגב, מול המדבקה הקדמית","על הבטן","על הירך","מתחת לבית השחי"],"מדבקה אחת על החזה ואחת על הגב ממולה."]],"images":[["infant-cpr--1-9-p-005-021.webp","בדיקת דופק בתינוק בעורק הזרוע (ברכיאלי)"],["infant-cpr--1-9-p-006-025.webp","עיסויים בתינוק: שתי אצבעות או טכניקת האגודלים"],["infant-cpr--1-9-p-011-054.webp","תינוק בהחייאה: ראש בתנוחה ניטרלית"]]},"choking":{"learn":[{"h":"אחרי שהגוף הזר יצא","steps":true,"items":["מעריכים נתיב אוויר, נשימה (קצב, מאמץ) וזילוח.","בודקים כיחלון מרכזי או היקפי.","נותנים חמצן.","ממשיכים לעקוב: לחיצות בטן וחזה עלולות לגרום לפגיעה פנימית, ולכן ממליצים על בדיקה בבית חולים."]},{"h":"זיהוי מהיר","steps":false,"items":["הנחנק לא מצליח לדבר או להשתעל, ולפעמים אוחז בגרון.","ראיות מהסביבה עוזרות: אוכל, צעצועים קטנים, מטבעות ליד תינוק או ילד.","חסימה חמורה דורשת התערבות מיידית."]}],"quiz":[["מה עושים מיד אחרי שהגוף הזר יצא?",["מעריכים נשימה וזילוח ונותנים חמצן","משחררים את המטופל הביתה","ממשיכים לחיצות בטן","מתחילים עיסויים"],"ממשיכים בהערכה ובטיפול; ייתכן נזק פנימי מהלחיצות."],["מה יכול לעזור לזהות חנק בתינוק שלא בוכה?",["ראיות בסביבה כמו חפצים קטנים או אוכל","מדידת חום","בדיקת אישונים","שאלה של התינוק"],"הסביבה מספרת את הסיפור כשהמטופל לא יכול."],["תינוק בחסימה חמורה. מה הסדר?",["5 טפיחות בגב ואז 5 לחיצות בחזה, והסתכלות בפה","5 לחיצות בטן","עיסויים בלבד","הנשמות בלבד"],"בתינוק לא עושים לחיצות בטן."]],"images":[["choking--1-9-p-019-092.webp","הסימן האוניברסלי לחנק: ידיים על הגרון"],["choking--1-9-p-021-101.webp","גוף זר חוסם את קנה הנשימה"],["choking--1-9-p-023-113.webp","טפיחות בגב בין השכמות"],["choking--1-9-p-023-114.webp","לחיצות בטן (היימליך)"]]},"terminology":{"learn":[{"h":"תכונות של חובש טוב","steps":false,"items":["יחסי אנוש, סובלנות ואמפתיה כלפי המטופל ומשפחתו.","אסרטיביות: לדעת לקבל החלטה ולהוביל, גם מול סביבה לחוצה.","כבוד לזולת ועבודת צוות.","משוב עצמי אחרי כל אירוע, רענון והרחבת ידע מקצועי ושמירה על כשירות."]},{"h":"למה צריך טרמינולוגיה","steps":false,"items":["זו השפה המשותפת של אנשי הרפואה, ומקורה בעיקר בלטינית וביוונית.","משתמשים בה במילוי טפסים ובתיעוד אירועים.","היא מאפשרת לקרוא סיכומי מחלה, הפניות ומכתבי שחרור של המטופל.","דוגמה: Abdominal GSW = פצע ירי בבטן; פצע כניסה ב-LLQ = ברבע השמאלי התחתון של הבטן."]},{"h":"עוד מונחים שכדאי להכיר","steps":false,"items":["Bi = דו, שני צדדים (Bilateral).","Post = אחרי (Postnatal), Pre = לפני (Preoperative).","Cerebro = מוח, Gastro = מערכת העיכול, Osteo = עצם, Phlebo = וריד, Thorax = בית החזה.","-centesis = ניקוב, -ostomy = פתיחה כירורגית, -paresis = שיתוק חלקי, -scopy = בדיקה במבט.","AMI = אוטם שריר הלב, CHF = אי-ספיקת לב, COPD = מחלת ריאות חסימתית כרונית, ICCU = טיפול נמרץ לב, ECG = אק\"ג."]}],"quiz":[["ממה מורכב מונח רפואי?",["קידומת, שורש וסיומת","שם המחלה ושם הרופא","מילה לטינית אחת בלבד","ראשי תיבות בלבד"],"מונח רפואי בנוי ממילת שורש שמעבירה את המשמעות העיקרית, ולעיתים קידומת וסיומת שמשנות אותה."],["מה המשמעות של Hypothermia?",["חום גוף נמוך","חום גוף גבוה","דופק איטי","לחץ דם נמוך"],"Hypo = מתחת, Therm = חום, ia = מצב. ירידה בטמפרטורת הגוף."],["מה פירוש הקיצור COPD?",["מחלת ריאות חסימתית כרונית","אי-ספיקת לב","אוטם שריר הלב","שבץ מוחי"],"Chronic Obstructive Pulmonary Disease."],["מה המשמעות של הסיומת -scopy?",["בדיקה במבט (בעזרת מכשיר)","כריתה","דלקת","פתיחה כירורגית"],"למשל Bronchoscopy: הסתכלות לתוך הסימפונות."],["מה זה Phlebo?",["וריד","עורק","עצם","מוח"],"Phlebo = וריד, למשל Phlebitis דלקת של וריד."],["פצע כניסה ב-LLQ. היכן הוא?",["ברבע השמאלי התחתון של הבטן","ברבע הימני העליון של הבטן","בחזה השמאלי","בגב התחתון"],"LLQ = Left Lower Quadrant."],["מה המשמעות של Bilateral?",["בשני הצדדים","בצד אחד","מעל","מאחור"],"Bi = שניים. Bilateral = דו-צדדי."],["איזו תכונה חשובה לחובש מול סביבה לחוצה ותובענית?",["אסרטיביות","ביישנות","היסוס","הימנעות מהחלטות"],"חובש צריך לדעת לקבל החלטה ולהוביל את הטיפול גם כשהסביבה לוחצת."]],"images":[["terminology--1-2-p-010-042.webp","מתא לרקמה, לאיבר ולמערכת"],["terminology--1-2-p-019-067.webp","מונחי תנוחה: Prone, Supine, Lateral Recumbent, Fowler, Trendelenburg"],["terminology--1-2-p-020-071.webp","מונחי תנועה: כיפוף, יישור, הרחקה, קירוב"],["terminology--1-2-p-021-075.webp","מישורי הגוף: סגיטלי, קורונלי וטרנסברסלי"]]},"field-practice":{"learn":[{"h":"עבודה בקשר (מירס)","steps":true,"items":["המוקד מדווח על האירוע בגל (מוקדן או רובוט).","הכונן עולה מול המוקד עם המספר שלו ומדווח יציאה לאירוע ופרטיו.","המוקדן מאשר ומעדכן במערכות.","מדברים מינימום בקשר ומדווחים רק מה שנדרש.","מדווחים הגעה, מקרה שונה ממה שדווח, צורך בכוננים נוספים או ציוד חסר."]},{"h":"פטירה מחוץ למוסד רפואי","steps":false,"items":["מדווחים למשטרה על כל פטירה מחוץ למוסד רפואי.","בפטירה בבית: מוסרים לנציג המשפחה דף וחוברת מידע על סידורי לוויה וקבורה.","במוסד רפואי או סיעודי האחריות על צוות המוסד; ברשות הרבים על המשטרה; במחנה צבאי על הצבא.","זיהוי לפי תעודה (ת\"ז, רישיון, דרכון, חוגר). בלי תעודה, לפי הסדר: קרוב מדרגה ראשונה, קרוב אחר, איש צוות המוסד, שכן או מכר."]},{"h":"מתי צוות ALS מפסיק החייאה","steps":false,"items":["אחרי 20 דקות החייאת ALS מלאה עם אסיסטולה או PEA.","כש-EtCO2 נמוך מ-10 מ\"מ כספית.","כשאין קולות לב בהאזנה.","כשיש סימנים למוות מוחי: אישונים מורחבים שלא מגיבים לאור, אין רפלקס קרנית ואין רפלקס עיני בובה."]}],"quiz":[["מה עושים בקשר אחרי שמגיעים לאירוע?",["מדווחים הגעה, כדי ששאר הכוננים ידעו","לא מדווחים כלום","מדווחים רק בסוף","מתקשרים לטלפון של המוקדן"],"דיווח הגעה מונע כפילות ומעדכן את כולם."],["אדם נפטר ברחוב. על מי האחריות להמשך?",["על המשטרה","על המשפחה","על הכונן","על בית החולים"],"פטירה ברשות הרבים באחריות המשטרה."],["אין תעודה מזהה לנפטר בבית. מי מזהה ראשון?",["קרוב משפחה מדרגה ראשונה","שכן","הכונן","המשטרה בלבד"],"הסדר: קרוב מדרגה ראשונה, קרוב אחר, איש צוות, שכן או מכר."],["מה מוסרים למשפחה בפטירה בבית?",["דף וחוברת מידע על סידורי לוויה וקבורה","את כל הציוד הרפואי","תעודת פטירה חתומה","שום דבר"],"זה חלק מהנוהל בפטירה בבית."],["איזה ערך EtCO2 הוא אחת הסיבות להפסקת החייאת ALS?",["נמוך מ-10 מ\"מ כספית","מעל 40","בדיוק 35","מעל 100"],"EtCO2 נמוך מאוד מעיד על זרימה לא יעילה."],["מה מותר לדבר בקשר?",["רק מה שנדרש לאירוע","שיחות חולין","עדכונים אישיים","הכול, אין הגבלה"],"שומרים על הגל מבצעי."]],"images":[]},"decisions":{"learn":[{"h":"תפקיד מנהל האירוע","steps":false,"items":["מגדיר את האירוע כאירוע חירום רפואי ומחליט איך לנהל אותו.","מרכז ומציג את המידע: לחץ דם, דופק, סוכר ועוד.","מפקח שההחלטות וההנחיות לאנשי הצוות מבוצעות.","מדווח למוקד.","מפריד בין מידע חשוב למידע שולי ונצמד לפרוטוקול."]},{"h":"עקרונות","steps":false,"items":["כל מקרה דומה לקודמים אבל תמיד שונה.","המדדים הם מידע חשוב לקבלת החלטה, ולא מחליפים את ההתרשמות מהמטופל.","פציעה קלה ובולטת עלולה להסתיר פגיעה קשה.","משדרים מקצועיות ומטפלים לפי התרחיש הגרוע ביותר."]}],"quiz":[["לפי איזה תרחיש מטפלים כשיש ספק?",["התרחיש הגרוע ביותר","התרחיש הסביר ביותר","מה שהמשפחה אומרת","התרחיש הקל ביותר"],"כך לא מפספסים מצב מסכן חיים."],["מה מתפקידי מנהל האירוע?",["לרכז את המידע ולפקח על ביצוע ההנחיות","לבצע את כל הפעולות בעצמו","לדבר עם התקשורת","לנהוג באמבולנס"],"המנהל מרכז, מפקח ומדווח למוקד."],["פצע מדמם בולט ברגל, והמטופל חיוור ומבולבל. מה הסכנה?",["שהפציעה הבולטת תסיח את הדעת מפגיעה קשה יותר","אין סכנה","שהדימום יעצור לבד","שהמטופל ישקר"],"מסיח דעת: הפציעה הבולטת לא בהכרח החשובה."]],"images":[]},"approach":{"learn":[{"h":"שאלות על כאב","steps":false,"items":["מתי התחיל? מה עשית כשזה התחיל?","איפה כואב, ומה סוג הכאב (לוחץ, דוקר, שורף)?","האם הכאב מקרין, ולאן?","עוצמה מ-1 עד 10.","רציף או לסירוגין, ומה מקל או מחמיר?"]},{"h":"סטורציה: מה משבש","steps":false,"items":["רעידות או התכווצויות.","חיישן הדוק או רופף מדי על האצבע.","ידיים קרות וזילוח ירוד.","הרעלת פחמן חד-חמצני (CO) מראה ערך גבוה מדי.","טפל בחולה, לא במכשיר."]},{"h":"E: מה מחפשים בהפשטה","steps":false,"items":["מדבקות רפואיות (למשל מדבקת כאב או ניטרטים).","אביזרים רפואיים: משאבת אינסולין, חיישן סוכר, קטטר שתן.","צמידים או שרשראות שמסמנים מחלה כרונית.","לא תמיד צריך הפשטה מלאה, ובסיום מכסים את המטופל ושומרים על צנעת הפרט."]},{"h":"העברה לצוות הבא","steps":true,"items":["מזהים את ראש הצוות ופונים אליו.","מעבירים את המידע שנאסף, ברור ותמציתי.","שואלים אם הצוות צריך עזרה.","אם יש מספיק מטפלים, מפנים את המקום לטובת המטופל והמשפחה."]}],"quiz":[["מה מבין אלה עלול לשבש קריאת סטורציה?",["חיישן רופף או ידיים קרות","גובה המטופל","צבע השיער","סוג הנעליים"],"רעידות, חיישן הדוק או רופף וזילוח ירוד משבשים את הקריאה."],["מה מחפשים בשלב E בנוסף לפציעות?",["מדבקות, משאבות, חיישנים וצמידים רפואיים","רק בגדים","את תעודת הזהות","את הטלפון של המטופל"],"הממצאים האלה מכוונים לאבחנה."],["מגיע צוות פינוי. למי מעבירים את המידע?",["לראש הצוות, בקצרה ובבירור","לכל אחד מהצוות בנפרד","למשפחה","לא מעבירים, הם יבדקו לבד"],"מזהים את ראש הצוות ומעבירים לו תמונת מצב."],["החולה נראה לא דחוף, אבל התגלתה בעיה מחשידה. מה עושים?",["מפנים באמבולנס וממשיכים לבדוק ולטפל בדרך","משחררים אותו","מחכים שעה","שולחים במונית"],"גם מטופל שנראה יציב יכול להחמיר."],["מה נכון לגבי ההקשבה לנוכחים?",["נותנים להם לספר עד הסוף ולא מאשימים","קוטעים אותם מהר","מתעלמים מהם","מבקשים שיעזבו מיד"],"המידע שלהם חשוב, במיוחד כשהמטופל לא יכול לדבר."],["מה מעיד עור רטוב ולח?",["הלם, חום, מצב לבבי או סוכרתי","מצב תקין תמיד","רק מאמץ גופני","התייבשות בלבד"],"עור לח הוא סימן אזהרה שדורש בדיקה נוספת."]],"images":[["approach--2-1-p-006-022.webp","התרשמות מהסביבה: בית מוזנח מספר משהו על המטופל"],["approach--2-1-p-022-080.webp","סדר הבדיקה: A B C D E"],["approach--2-1-p-014-049.webp","מד סטורציה על האצבע"],["approach--2-1-p-016-056.webp","מישוש דופק רדיאלי בשורש כף היד"],["approach--2-1-p-018-065.webp","מדידת לחץ דם: ניפוח השרוול עד שהדופק נעלם"],["approach--2-1-p-017-062.webp","טבלת ערכי לחץ דם: תקין עד יתר לחץ דם חמור"]]},"unconscious":{"learn":[{"h":"מה עושים קודם","steps":false,"items":["מתשאלים נוכחים שראו את האירוע: מה קרה, כמה זמן, האם היה פרכוס או חבלה.","לוקחים מדדים מלאים: נשימה, דופק, לחץ דם, סטורציה וסוכר.","מחפשים רמזים בזירה: תרופות, מזרקים, בקבוקים, מסמכים רפואיים."]}],"quiz":[["מגיעים למחוסר הכרה שנושם. ממי מקבלים מידע?",["מנוכחים שראו את האירוע","רק מהמטופל","רק מהמוקד","לא שואלים, רק מטפלים"],"עדים יכולים לספר אם היה פרכוס, נפילה או תלונה מקדימה."],["איזו בדיקה חובה בכל מחוסר הכרה?",["רמת סוכר בדם","בדיקת שמיעה","בדיקת עיניים בלבד","מדידת גובה"],"היפוגליקמיה היא גורם נפוץ והפיך."]],"images":[["unconscious--2-2-p-004-015.webp","פרוטוקול BLS למחוסר הכרה נושם"]]},"seizures":{"learn":[{"h":"שלבי ההתקף הגדול, בסדר","steps":true,"items":["טוני: התכווצות של כל שרירי הגוף, לעיתים כחלון כי הנשימה נפגעת.","היפרטוני: הגוף מתקשח לגמרי.","קלוני: התכווצויות והרפיות חוזרות בקצב, ולפעמים הפרשה מוקצפת מהפה.","פוסט-פרכוס (פוסט-איקטלי): ישנוני, מבולבל, לעיתים כאב ראש וחולשה."]},{"h":"פרכוסי חום: מה עוד חשוב","steps":false,"items":["סיכוי גבוה שהפרכוס יחזור ב-24 השעות הראשונות.","פרכוס ראשון: תמיד מפנים לבית חולים, גם אם נראה שזה מהחום.","מורידים שכבות ביגוד ומשאירים שכבה אחת.","מפנים באמבולנס למלר\"ד."]}],"quiz":[["באיזה שלב של ההתקף הגדול יש התכווצויות והרפיות חוזרות?",["השלב הקלוני","השלב הטוני","השלב הפוסט-איקטלי","השלב ההיפרטוני"],"קלוני = התכווצויות קצביות חוזרות."],["מה הסיכון אחרי פרכוס חום?",["שהפרכוס יחזור ב-24 השעות הראשונות","שהילד יאבד את הראייה","שיופיע שבץ","אין סיכון"],"לכן מפנים לבית חולים, במיוחד בפרכוס ראשון."],["חולה מפרכס שוכב על מיטה. מה עושים?",["מונעים ממנו ליפול לרצפה ומרפדים סביבו","קושרים אותו למיטה","מחזיקים אותו חזק","מכניסים לו משהו לפה"],"לא עוצרים פרכוס בכוח, רק מונעים פגיעה."],["איך נקרא גם התקף קטן?",["התקף היעדרות (אבסנס)","סטטוס אפילפטיקוס","התקף טוני","פרכוס חום"],"קצר, החולה 'נעדר' לרגעים."],["למה לא מכניסים דבר לפה של חולה מפרכס?",["זה עלול לגרום להקאה, שאיפה או עווית בגרון","זה עוצר את הפרכוס","זה מגן על הלשון","זה מותר רק לרופא"],"הכנסת חפצים לפה מסוכנת."]],"images":[["seizures--2-2-p-007-026.webp","השלב הטוני והשלב הקלוני"],["seizures--2-2-p-008-030.webp","שלבי התקף גדול עד המצב הפוסט-איקטלי"],["seizures--2-2-p-019-059.webp","פרוטוקול BLS לפרכוסים"],["seizures--2-2-p-026-087.webp","לא שופכים מים על מפרכס"],["seizures--2-2-p-026-088.webp","לא מכים ולא מטלטלים מפרכס"]]},"syncope":{"learn":[{"h":"עלפון לעומת פרכוס","steps":false,"items":["עלפון קורה לרוב בעמידה; פרכוס בכל תנוחה.","בעלפון החולה זוכר שהרגיש רע לפני; פרכוס יכול להתחיל בלי אזהרה.","בעלפון החזרה להכרה מהירה, תוך דקה-שתיים; אחרי פרכוס יש בלבול ממושך.","אם לא חוזרים להכרה מהר, חושדים בבעיה רפואית חמורה ומזמינים ALS."]}],"quiz":[["אדם עומד ואומר שמסתובב לו הראש ושהוא מזיע. מה עושים?",["משכיבים ומגביהים רגליים","נותנים לו לעמוד","מושיבים על כיסא גבוה","נותנים לו לרוץ"],"השכבה לפני העלפון מונעת נפילה ומחזירה דם למוח."],["מה הסכנה העיקרית בזמן עלפון?",["חבלה מהנפילה, למשל בראש או שברים","פרכוס בטוח","דום לב תמיד","היפותרמיה"],"הנפילה עצמה היא הסכנה הנפוצה."],["אדם התעלף. מה אסור לעשות?",["להעמיד או להושיב אותו מהר","להגביה רגליים","לבדוק נשימה","להזמין עזרה"],"קימה מהירה עלולה לגרום לעלפון חוזר."]],"images":[["syncope--2-2-p-021-071.webp","סימנים מקדימים: סחרחורת וחולשה"],["syncope--2-2-p-025-083.webp","פציעה מנפילה בזמן עלפון"]]},"neuro-emerg":{"learn":[{"h":"גורמי סיכון לאירוע מוחי","steps":false,"items":["גורמים שאי אפשר לשנות: גיל, תורשה וגנטיקה, מין.","גורמים שאפשר לשנות: יתר לחץ דם, עישון, סוכרת, כולסטרול, השמנה, פרפור עליות, אלכוהול.","חבלת ראש קלה אצל מטופל שנוטל מדללי דם מעלה סיכון לדימום מוחי."]},{"h":"CVA או TIA?","steps":false,"items":["בשטח, כשהסימנים עדיין קיימים, אי אפשר להבדיל ביניהם.","גם כשהסימנים חלפו מפנים לבית חולים, כי TIA מבשר לעיתים אירוע מוחי.","שואלים ומתעדים מתי המטופל נראה תקין בפעם האחרונה."]},{"h":"סימנים נוספים מעבר ל-FAST","steps":false,"items":["ראייה כפולה או אובדן ראייה פתאומי.","חוסר תחושה או נימול בצד אחד של הגוף.","כאב ראש פתאומי וחזק מאוד.","בלבול, סחרחורת ואיבוד שיווי משקל."]}],"quiz":[["מה מבין אלה גורם סיכון לאירוע מוחי שאי אפשר לשנות?",["גיל","עישון","יתר לחץ דם","השמנה"],"גיל, תורשה ומין הם גורמים קבועים."],["מטופל נוטל מדללי דם ונחבל קלות בראש. למה לשים לב?",["לסיכון מוגבר לדימום מוחי","אין צורך בבדיקה","לשבר ביד","להתייבשות"],"מדללי דם מגבירים דימום, גם בחבלה קלה."],["מה חשוב לברר בחשד לאירוע מוחי?",["מתי המטופל נראה תקין בפעם האחרונה","מה צבע העיניים","מה אכל אתמול","מה מספר הנעליים"],"זמן התחלת התסמינים קובע את אפשרויות הטיפול בבית החולים."],["מה מייצגת ה-S ב-FAST?",["Speech: בעיות בדיבור","Smile","Sugar","Stroke"],"Face, Arm, Speech, Time."],["סימני אירוע מוחי עדיין קיימים. אפשר לדעת בשטח אם זה TIA?",["לא, אי אפשר להבדיל עד שהסימנים חולפים","כן, לפי לחץ הדם","כן, לפי הדופק","כן, לפי הגיל"],"בשטח מתייחסים לכל מקרה כאירוע מוחי ומפנים."]],"images":[["neuro-emerg--2-3-p-006-022.webp","אירוע מוחי איסכמי (חסימה) לעומת המורגי (דימום)"],["neuro-emerg--2-3-p-007-025.webp","אירוע מוחי איסכמי: קריש חוסם עורק במוח"],["neuro-emerg--2-3-p-008-028.webp","אירוע מוחי המורגי: קרע של כלי דם"],["neuro-emerg--2-3-p-010-033.webp","TIA: חסימה זמנית; שבץ: חסימה מלאה ומוות תאים"],["neuro-emerg--2-3-p-011-036.webp","בדיקת FAST: פנים, ידיים, דיבור, זמן"]]},"diabetes-tox":{"learn":[{"h":"סוכרת במספרים","steps":false,"items":["ב-2021 היו בישראל כ-548,000 מבוגרים מאובחנים עם סוכרת (9.8%), ועוד כ-3,300 ילדים ובני נוער.","הסוכרת וסיבוכיה אחראים לכ-6-7% ממקרי המוות.","סוכרת סוג 2 קשורה לעודף משקל ולחוסר פעילות, ומופיעה היום גם בילדים."]},{"h":"הלבלב והאינסולין","steps":false,"items":["הלבלב באורך כ-15 ס\"מ, ברבע השמאלי העליון של הבטן.","האינסולין מכניס גלוקוז לתאים ובכך מוריד את רמתו בדם.","בצום הגלוקוז 70-100 מ\"ג/ד\"ל; בשעה אחרי ארוחה הוא יכול לעלות לכ-140.","הכליות מחזירות גלוקוז לדם עד רמה של 180; מעל זה הוא יוצא בשתן ומושך איתו מים."]},{"h":"היפר או היפו: איך מבדילים","steps":false,"items":["היפרגליקמיה מתפתחת בהדרגה, במשך ימים: צמא, יובש בפה, השתנה מרובה, ולעיתים נשימה עמוקה וריח אצטון (DKA).","היפוגליקמיה מתפתחת מהר, תוך דקות: הזעה, רעב, ריור, בלבול, ירידה בהכרה ופרכוסים.","HIGH במכשיר הוא בדרך כלל מעל 600; LOW הוא בדרך כלל מתחת ל-30.","הסימנים יכולים להיראות כמו שכרות, אבל זה מצב חירום."]},{"h":"מרכז מידע להרעלות","steps":false,"items":["מרכז המידע הארצי להרעלות נמצא ברמב\"ם: 04-777-1900.","אפשר להתייעץ בו על תרופות, חומרי ניקוי, הכשות נחש, עקיצות עקרב והרעלות מזון.","באנמנזה: איזה חומר, כמה, מתי, האם שולב אלכוהול, גיל הנפגע והסימנים."]}],"quiz":[["מעל איזו רמת סוכר בדם הכליות מתחילות להפריש גלוקוז בשתן?",["180 מ\"ג/ד\"ל","70","100","600"],"מעל 180 הגלוקוז לא נספג כולו מחדש."],["מה מאפיין את קצב ההתפתחות של היפוגליקמיה?",["מהיר, תוך דקות","איטי, תוך ימים","שבועות","לא משתנה"],"היפוגליקמיה מתדרדרת מהר; היפרגליקמיה מתפתחת בהדרגה."],["מה מאפיין את קצב ההתפתחות של היפרגליקמיה?",["הדרגתי, תוך כמה ימים","תוך שניות","תוך דקות","רק בלילה"],"היפרגליקמיה מתפתחת לאט."],["מה בדרך כלל אומר HIGH במד הסוכר?",["ערך מעל 600","ערך מתחת ל-30","מכשיר תקול תמיד","ערך תקין"],"HIGH מעיד בדרך כלל על ערך גבוה מ-600."],["מה מספר מרכז המידע להרעלות?",["04-777-1900 (רמב\"ם)","101","100","03-5303030"],"המרכז הארצי פועל ברמב\"ם."],["חולה סוכרת מבולבל ומזיע, נראה כמו שיכור. מה עושים קודם?",["מודדים סוכר","שולחים הביתה","נותנים קפה","מחכים שיתפכח"],"היפוגליקמיה יכולה להיראות כמו שכרות."],["היכן נמצא הלבלב?",["ברבע השמאלי העליון של הבטן, לכיוון המרכז","ברבע הימני התחתון","מאחורי הלב","באגן"],"הלבלב קטן, כ-15 ס\"מ."],["מה מבין אלה עלול לגרום ל-LOW שגוי?",["מקלונים פגי תוקף או כמות דם קטנה מדי","ידיים חמות","מטופל רגוע","סוללה חדשה"],"תמיד בודקים את המכשיר והמקלונים."],["ניסיון התאבדות בתרופות. מה מנסים למצוא בזירה?",["את קופסת התרופה, כדי לדעת איזו תרופה וכמה","את הטלפון של המטופל","מסמכי ביטוח","שום דבר"],"זיהוי החומר והכמות עוזר מאוד לבית החולים."]],"images":[["diabetes-tox--2-4-p-007-025.webp","הלבלב, הכבד וכיס המרה"],["diabetes-tox--2-4-p-010-036.webp","האינסולין פותח את התא לכניסת גלוקוז"],["diabetes-tox--2-4-p-011-039.webp","ויסות הסוכר: אינסולין מוריד, גלוקגון מעלה"],["diabetes-tox--2-4-p-024-101.webp","משאבות אינסולין"],["diabetes-tox--2-4-p-024-102.webp","חיישן סוכר רציף על הזרוע"],["diabetes-tox--2-4-p-026-111.webp","מדידת סוכר מהאצבע"],["diabetes-tox--2-4-p-037-149.webp","מקורות נפוצים להרעלת פחמן חד-חמצני בבית"]]},"resp-emerg":{"learn":[{"h":"חמשת הנכונים לפני הזרקה","steps":false,"items":["מטופל: מוודאים שהוא עומד בקריטריונים להזרקה.","מינון: 0.15 מ\"ג מתחת לגיל 10, 0.3 מ\"ג מגיל 10.","מועד: בזמן הנכון, ובודקים את תוקף הערכה (לא של פריט בודד בתוכה).","תרופה: בודקים שזו התרופה הנכונה שלוש פעמים: בהוצאה, לפני השאיבה ולפני ההזרקה, ואם יש מטפל נוסף, יחד איתו.","מקום: לשריר. ירך מתחת לגיל 10, כתף מגיל 10."]},{"h":"אחרי ההזרקה","steps":true,"items":["מזריקים בזווית של 90 מעלות לעור מתוח, ומחכים 5 שניות.","לא מכסים את המחט ולא מפרידים אותה ביד; משליכים למכל חדים.","מעסים את המקום כחצי דקה.","שומרים את האמפולה ומראים אותה לצוות ALS, וממלאים טופס תיעוד.","אין שיפור אחרי 5-10 דקות: אפשר מנה נוספת. אין שיפור אחרי 2 מנות: מתייעצים עם המוקד הרפואי."]},{"h":"COPD בקצרה","steps":false,"items":["COPD היא גורם המוות הרביעי בעולם, וכ-3,000 חולים מתים ממנה בישראל בכל שנה.","שם כולל לאמפיזמה (הרס דפנות הנאדיות) ולברונכיטיס כרונית (ליחה מרובה).","לרוב יש היסטוריה של עישון כבד ושיעול יומי עם ליחה.","זו מחלה כרונית, והחולה בדרך כלל יודע לתאר מה 'רגיל' אצלו ומה חדש."]},{"h":"תסחיף ריאתי ודלקת ריאות","steps":false,"items":["תסחיף: קריש חוסם עורק בריאה, ולכן יש אוויר בנאדיות אבל אין זרימת דם שתיקח את החמצן.","גורמי סיכון לתסחיף: קיבוע, ניתוח, טיסה ארוכה או חוסר תנועה ממושך.","תסמיני תסחיף: קוצר נשימה פתאומי, כאב חד בנשימה, שיעול לעיתים עם דם.","דלקת ריאות: זיהום שממלא את הנאדיות בנוזל דלקתי; חום, שיעול עם ליחה וקוצר נשימה."]}],"quiz":[["מה מינון האדרנלין IM לילד בן 7?",["0.15 מ\"ג","0.3 מ\"ג","0.5 מ\"ג","1 מ\"ג"],"מתחת לגיל 10: 0.15 מ\"ג; מגיל 10: 0.3 מ\"ג."],["היכן מזריקים אדרנלין לילד בן 8?",["בשריר הירך","בכתף","בבטן","בעכוז"],"מתחת לגיל 10 בירך, מעל גיל 10 בכתף."],["כמה פעמים מוודאים שזו התרופה הנכונה?",["שלוש: בהוצאה, לפני השאיבה ולפני ההזרקה","פעם אחת","פעמיים","לא צריך, הערכה מסודרת"],"בדיקה משולשת מונעת טעות."],["10 דקות אחרי הזרקה אין שיפור. מה עושים?",["אפשר לתת מנה נוספת","מחכים עוד שעה","נותנים שלוש מנות ברצף","מפסיקים לטפל"],"אין שיפור אחרי 2 מנות: מתייעצים עם המוקד הרפואי."],["מה עושים עם האמפולה אחרי ההזרקה?",["שומרים ומראים לצוות ALS","זורקים לפח רגיל","מחזירים לערכה","משאירים אצל המשפחה"],"הצוות הבא צריך לדעת מה ניתן."],["מטופל חזר מטיסה ארוכה עם קוצר נשימה פתאומי וכאב חד בנשימה. מה החשד?",["תסחיף ריאתי","אסתמה","היפרוונטילציה","דלקת גרון"],"חוסר תנועה ממושך מגביר יצירת קרישים."],["מה קורה בתסחיף ריאתי?",["קריש חוסם עורק בריאה ופוגע בפרפוזיה","הנאדיות מתמלאות בליחה","הסימפונות מתכווצים מאלרגיה","הקנה נחסם בגוף זר"],"יש אוויר אבל אין דם שיקבל את החמצן."]],"images":[["resp-emerg--2-5-p-007-027.webp","אסתמה: נתיב אוויר תקין לעומת דלקתי ומכווץ"],["resp-emerg--2-5-p-012-042.webp","COPD: מחלת ריאות חסימתית כרונית"],["resp-emerg--2-5-p-014-047.webp","תנוחת חצובה (טריפוד) במצוקה נשימתית"],["resp-emerg--2-5-p-018-063.webp","אנפילקסיס: התכווצות והיצרות של דרכי האוויר"],["resp-emerg--2-5-p-021-071.webp","נפיחות של הלשון והשפתיים בתגובה אלרגית"],["resp-emerg--2-5-p-035-118.webp","מקום ההזרקה של אפיפן: הצד החיצוני של הירך"],["resp-emerg--2-5-p-038-126.webp","הזרקת אפיפן לירך"],["resp-emerg--2-5-p-034-113.webp","לא מזריקים אדרנלין ללא אישור ובאזור לא מתאים"],["resp-emerg--2-5-p-053-172.webp","פרוטוקול BLS למצוקה נשימתית"]]},"cardiac-emerg":{"learn":[{"h":"תעוקה יציבה או לא יציבה","steps":false,"items":["יציבה: מתחילה במאמץ, ידועה לחולה, וחולפת אחרי 5-15 דקות מנוחה.","לא יציבה: מופיעה במנוחה, חזקה או ארוכה מהרגיל, או לא חולפת במנוחה.","תעוקה לא יציבה מטופלת כמו אוטם: ACS, אספירין לפי הפרוטוקול ו-ALS."]},{"h":"אי-ספיקת לב: שמאל או ימין","steps":false,"items":["שמאל (הנפוצה): הלב לא מזרים מספיק דם מחומצן לגוף; הדם נערם בריאות ויוצר בצקת ריאות.","ימין: מתפתחת לרוב בעקבות אי-ספיקת לב שמאל; הדם נערם בגוף: בצקות ברגליים, ורידי צוואר בולטים.","סימני החמרה: קוצר נשימה בשכיבה, שינה בישיבה, התעוררות בלילה עם קוצר נשימה, השתנה מרובה בלילה."]},{"h":"דופק חריג: שיקול דעת","steps":false,"items":["דופק סדיר 50-60 או 100-150 בדקה: שוקלים לפי המצב הכללי.","מחפשים סיבה: חום, התייבשות או כאב יכולים להסביר דופק מהיר.","דוגמה: צעיר מיובש אחרי טיול ביום חם עם דופק 130 – כנראה תגובה להתייבשות; עדיין מודדים, נותנים טיפול ומעריכים שוב.","יש ספק? אין ספק: מזמינים ALS."]},{"h":"כאב בחזה שאינו מהלב","steps":false,"items":["מקור שרירי-שלדי: הכאב משתנה במגע, בתזוזה או בנשימה עמוקה.","מקור במערכת העיכול: לעיתים מורגש בחזה.","מפרצת באבי העורקים: כאב בבטן או בגב, לעיתים אזור פועם.","החובש לא יכול לאבחן את מקור הכאב, ולכן כל כאב בחזה מטופל כאילו הוא לבבי עד שיוכח אחרת."]}],"quiz":[["מה מאפיין תעוקה לא יציבה?",["כאב במנוחה או כאב שלא חולף במנוחה","כאב שחולף אחרי 5 דקות מנוחה","כאב רק בשרירי הרגליים","כאב שמשתנה במגע"],"תעוקה לא יציבה מסוכנת ומטופלת כמו אוטם."],["איזו אי-ספיקת לב גורמת לבצקת ריאות?",["אי-ספיקת לב שמאלית","אי-ספיקת לב ימנית","אף אחת","רק תעוקה"],"הדם נערם בריאות כשהלב השמאלי לא מצליח לשאוב אותו."],["כאב בחזה שמחמיר כשלוחצים על הצלעות. מה זה אומר לחובש?",["ייתכן מקור שרירי-שלדי, אבל עדיין מטפלים כאילו זה לבבי","שזה בוודאות לא לבבי ואפשר לשחרר","שזה אוטם בוודאות","שצריך לתת אספירין כפול"],"החובש לא מאבחן את מקור הכאב."],["מה מאפיין אי-ספיקת לב ימנית?",["בצקות ברגליים וורידי צוואר בולטים","ליחה ורודה מוקצפת בלבד","כאב בזרוע שמאל בלבד","דופק איטי מאוד"],"הדם נערם במחזור הגדול."],["סביב איזה גיל מתחילה היום מחלת הלב בממוצע, לפי המצגת?",["35-40","15-20","70-80","מעל 90"],"הגיל יורד בהדרגה."]],"images":[["cardiac-emerg--2-6-p-007-032.webp","טרשת עורקים: היווצרות רובד וקרע שלו"],["cardiac-emerg--2-6-p-008-036.webp","חסימה בעורק כלילי פוגעת בשריר הלב"],["cardiac-emerg--2-6-p-014-062.webp","מעורק בריא לאוטם שריר הלב"],["cardiac-emerg--2-6-p-016-069.webp","הקרנת כאב אופיינית: חזה, זרוע, גב, לסת ובטן עליונה"],["cardiac-emerg--2-6-p-011-049.webp","ניטרו בתרסיס מתחת ללשון"],["cardiac-emerg--2-6-p-024-101.webp","אספירין לעיסה"],["cardiac-emerg--2-6-p-028-113.webp","בצקת ריאות: נוזל בנאדיות"],["cardiac-emerg--2-6-p-022-092.webp","פרוטוקול BLS לכאבים בחזה"]]},"trauma-intro":{"learn":[{"h":"מה מקטין את הנזק ברכב","steps":false,"items":["חגורת בטיחות חגורה כראוי מאטה את הנוסע יחד עם הרכב ומונעת פגיעה בדפנות.","כריות אוויר יוצרות כר שסופג את הפגיעה.","כיסא בטיחות מתאים לגיל וקבוע כראוי מפחית מאוד את חומרת הפגיעה בילד."]},{"h":"לקרוא את הזירה","steps":false,"items":["שמשה סדוקה בצורת עכביש: הראש פגע בה; חושדים בפגיעת ראש ועמוד שדרה.","הגה עקום: פגיעה בחזה ובבטן.","שואלים: מאיזה כיוון הייתה הפגיעה, באיזו מהירות, האם הנוסעים היו חגורים.","באופנוע: 'תסמונת הקליע האנושי' – הראש והקסדה מושכים את הגוף קדימה, והרגליים נפגעות."]},{"h":"פצעי ירי ופיצוץ","steps":false,"items":["חור היציאה בדרך כלל גדול יותר ופחות מוגדר מחור הכניסה.","אי אפשר לדעת בשטח את המסלול של הקליע בתוך הגוף.","פיצוץ: שלב 1 גל הדף (ריאות, אוזניים, בטן), שלב 2 רסיסים, שלב 3 הנפגע עף ופוגע בעצמים, שלב 4 כוויות.","בכל פיצוץ חוששים מפיצוץ משני, במיוחד בפיגוע ובאירוע חומ\"ס."]}],"quiz":[["שמשה קדמית סדוקה בצורת עכביש מעידה על:",["פגיעת ראש וחשד לפגיעה בעמוד השדרה","פגיעה ברגליים בלבד","שאין פגיעה","פגיעה בגב התחתון"],"הראש הוא שפגע בשמשה."],["מה נכון לגבי חור היציאה בפצע ירי?",["בדרך כלל גדול יותר ופחות מוגדר מחור הכניסה","תמיד קטן יותר","תמיד אין חור יציאה","תמיד בגב"],"ולא ניתן לדעת את מסלול הקליע."],["מה גורם השלב השני בפיצוץ?",["פגיעות מרסיסים","גל הדף בריאות","כוויות","נפילה"],"שלב 1 הדף, 2 רסיסים, 3 הטחה, 4 כוויות."],["פיגוע עם מטען. ממה צריך לחשוש בזירה?",["ממטען נוסף (פיצוץ משני)","מגשם","מהקהל בלבד","מקור"],"בטיחות הצוות קודמת."],["מה התפקיד של חגורת הבטיחות?",["להאט את הנוסע יחד עם הרכב ולמנוע פגיעה בדפנות","לייפות את הרכב","להאיץ את הרכב","אין לה תפקיד בתאונה"],"נוסע לא חגור ממשיך לנוע ומתנגש בהגה או בשמשה."]],"images":[["trauma-intro--3-1-p-008-032.webp","מנגנוני תאונת דרכים: צד, אחור, חזית, התהפכות, הולך רגל"],["trauma-intro--3-1-p-005-021.webp","מבחן ריסוק: מה קורה לנוסעים בהתנגשות ב-40 קמ\"ש"],["trauma-intro--3-1-p-006-026.webp","נזק לרכב מרמז על עוצמת הפגיעה בנוסעים"],["trauma-intro--3-1-p-012-045.webp","תאונת אופנוע: לרוכב אין שלדת רכב שמגנה עליו"]]},"trauma-approach":{"learn":[{"h":"שלושת גלי התמותה","steps":false,"items":["גל ראשון: שניות עד דקות, מפגיעה קטלנית במוח, בלב או בכלי דם גדולים. כמעט אי אפשר להציל, ולכן המפתח הוא מניעה.","גל שני: הדקות והשעות הראשונות, מדימום, פגיעה בנתיב אוויר או בנשימה. כאן הטיפול בשטח והפינוי המהיר מצילים חיים.","גל שלישי: שעות עד חודשים, מזיהומים ואי-ספיקת איברים."]},{"h":"מאיפה בא PHTLS","steps":false,"items":["בעבר טיפלו בכל נפגע באותה שיטה ארוכה בשטח, או לחלופין 'Scoop and Run': העמסה ופינוי בלי טיפול.","PHTLS משלב את שתי הגישות: בשטח עושים רק בדיקות וטיפולים מצילי חיים, ומיד מפנים.","בנפגע קשה אולי לא מגיעים בכלל לסבב השניוני, והוא מתבצע בדרך אם אפשר."]},{"h":"דגשים בסבב הראשוני","steps":false,"items":["הערכת הסביבה מתחילה כבר מקבלת הקריאה: מצב הכבישים, הסכנות הצפויות והציוד שצריך.","X: אם צריך, חושפים מוקדם כדי למצוא את מקור הדימום, ועוצרים אותו באמצעי המהיר והיעיל ביותר.","D: AVPU, תנועה ותחושה בגפיים, ואישונים (קוטר, שוויון ותגובה לאור).","E: מעבירים ידיים גם על הגב, החלק האחורי של הראש והגפיים, ומכסים את הנפגע למניעת היפותרמיה."]}],"quiz":[["באיזה גל תמותה הטיפול בשטח משפיע הכי הרבה?",["בגל השני: הדקות והשעות הראשונות","בגל הראשון: שניות","בגל השלישי: שבועות","אין השפעה"],"דימום ובעיות נתיב אוויר ונשימה ניתנים לטיפול."],["מה היה 'Scoop and Run'?",["העמסה ופינוי מהירים בלי טיפול בשטח","טיפול ארוך בשטח","טיפול רק בבית חולים","שיטה לעצירת דימום"],"PHTLS מכליא בינה לבין טיפול מלא בשטח."],["נפגע דחוף לפינוי. האם מתעכבים בשטח כדי לפתוח עירוי?",["לא, מפנים בלי עיכוב, וטיפולים נוספים בדרך","כן, תמיד","רק אם הוא בהכרה","רק בלילה"],"כל טיפול מעבר לסבב הראשוני נעשה בדרך."],["מה בודקים באישונים בשלב D?",["קוטר, שוויון ותגובה לאור","רק צבע","רק אם הם פתוחים","שום דבר"],"אישונים לא שווים מחשידים לפגיעת ראש."],["למה מכסים את הנפגע בשלב E?",["כדי למנוע היפותרמיה, שמחמירה דימום","כדי שלא יראו אותו","כדי שלא יזוז","אין סיבה"],"קור פוגע ביכולת הקרישה."]],"images":[]},"shock-bleeding":{"learn":[{"h":"מה הגוף עושה כדי לפצות","steps":false,"items":["מערכת העצבים הסימפתטית מאיצה את הלב ומכווצת כלי דם בפריפריה, כדי לשמור דם למוח, ללב ולכליות.","הנשימה מואצת ועמוקה יותר.","הכליות מפחיתות את כמות השתן, ומערכת העיכול מאטה.","כשהפיצוי קורס, לחץ הדם יורד והנפגע מתדרדר מהר מאוד."]},{"h":"עוד סוגי הלם","steps":false,"items":["אנפילקטי: היסטמין מרחיב כלי דם ומגביר את חדירותם, יחד עם בצקות ופגיעה בנשימה.","ספטי: החמרה של זיהום; נשימה מהירה, דופק מהיר וחלש, מילוי קפילרי מאורך, בלבול.","נוירוגני: פגיעה בעמוד השדרה, כלי הדם מתרחבים מתחת לפגיעה, לחץ דם נמוך כבר מההתחלה.","קרדיוגני: הלב עצמו לא מזרים מספיק, למשל אחרי אוטם."]},{"h":"תחבושת ישראלית ופקינג","steps":false,"items":["התחבושת הישראלית משלבת פד ואגד אלסטי, ואפשר להגביר בה לחץ בעזרת האבזם.","אחרי חבישה בודקים שיש דופק מתחת לחבישה.","פקינג (בסמכות חובש ומעלה): ממלאים את הפצע בגזה אצבע אחר אצבע, ולוחצים 3 דקות בתחבושת המוסטטית או 10 דקות בגזה רגילה.","בפצעי דקירה צרים פקינג עלול להיות בעייתי; לא מרחיבים את פתח הפצע."]},{"h":"חוסם עורקים: דגשים","steps":false,"items":["מתי: דימום מסכן חיים מגפה, קטיעה, נפגע מעורפל או מחוסר הכרה, או בעיה ב-A או B שדורשת את הידיים שלך.","הדימום לא נעצר: מוסיפים חוסם שני, צמוד לראשון ומעליו.","רושמים את השעה ב-4 ספרות.","המרת חוסם רק באישור המוקד הרפואי: חוסם חדש מוכן, חבישה לוחצת קודם, שחרור איטי, ואם הדימום חוזר מהדקים שוב."]}],"quiz":[["איך הגוף מפצה בשלב המוקדם של הלם?",["מאיץ את הלב ומכווץ כלי דם בפריפריה","מאט את הלב","מרחיב את כל כלי הדם","מעלה את תפוקת השתן"],"כך נשמר דם לאיברים החיוניים."],["חוסם עורקים לא עצר את הדימום. מה עושים?",["מוסיפים חוסם שני צמוד לראשון ומעליו","מורידים אותו","שמים חוסם מתחת לפצע","מחכים"],"החוסם השני מגביר את הלחץ."],["כמה זמן לוחצים על פקינג בגזה רגילה?",["10 דקות","דקה","30 שניות","שעה"],"עם תחבושת המוסטטית 3 דקות."],["באיזה מצב מותר להמיר חוסם עורקים?",["רק באישור המוקד הרפואי ועם חוסם חדש מוכן","תמיד אחרי 10 דקות","כשהפצוע מבקש","אף פעם"],"המרה היא פעולה חריגה."],["מה בודקים אחרי חבישה לוחצת על גפה?",["שיש דופק בגפה מתחת לחבישה","את צבע החבישה בלבד","את החום","שום דבר"],"חבישה הדוקה מדי עוצרת את כל הזרימה."],["אילו סימנים מתאימים להלם ספטי?",["חום או זיהום, נשימה מהירה, דופק מהיר וחלש ובלבול","דופק איטי ועור אדום מתחת לפגיעה","פריחה מגרדת בלבד","כאב בחזה בלבד"],"ספסיס הוא החמרה של זיהום."]],"images":[["shock-bleeding--3-3-p-003-013.webp","סוגי הלם: היפוולמי, קרדיוגני, חסימתי, דיסטריבוטיבי, נוירוגני"],["shock-bleeding--3-3-p-022-097.webp","לחץ ישיר על פצע מדמם"],["shock-bleeding--3-3-p-026-115.webp","תחבושת אישית (בנדאז' לחץ)"],["shock-bleeding--3-3-p-028-124.webp","חבישה לוחצת על הגפה"],["shock-bleeding--3-3-p-028-125.webp","חבישה לוחצת על הראש"],["shock-bleeding--3-3-p-030-137.webp","אזורי צומת (מפשעה, בית שחי, צוואר) שבהם אי אפשר לשים חוסם"],["shock-bleeding--3-3-p-036-156.webp","קטיעה: דימום שדורש חוסם עורקים"],["shock-bleeding--3-3-p-037-159.webp","שלבי הנחת חוסם עורקים (CAT)"],["shock-bleeding--3-3-p-037-160.webp","הידוק המוט, נעילה ורישום שעת ההנחה"],["shock-bleeding--3-3-p-041-178.webp","חוסם עורקים מאולתר עם משולש בד ומוט"],["shock-bleeding--3-3-p-044-194.webp","סימני הלם מפוצה לעומת הלם לא מפוצה"],["shock-bleeding--3-3-p-045-199.webp","דרגות דימום לפי כמות הדם שאבדה"]]},"head-neck":{"learn":[{"h":"הגולגולת והקרומים","steps":false,"items":["הגולגולת בנויה מעצמות שטוחות שמחוברות בתפרים. היא מגינה טוב מפגיעה ישירה, אבל לא מאפשרת למוח להתרחב.","לכן דימום או נפיחות בתוכה מעלים את הלחץ התוך-גולגלתי.","מתחת לעצם יש שלושה קרומים: דורה, ארכנואיד ופיה. בין הקרומים יש חללים שיכולים להתמלא בדם.","נוזל השדרה (CSF) מבודד, תומך ומזין את המוח ואת חוט השדרה."]},{"h":"פגיעה בלי שבר","steps":false,"items":["בעצירה פתאומית המוח ממשיך לנוע ופוגע בדופן הגולגולת.","הוא נהדף חזרה ופוגע בדופן הנגדית, ולפעמים הפגיעה השנייה חמורה יותר.","נפיחות חיצונית בקרקפת לא שוללת דימום בפנים.","פגיעה באונה המצחית יכולה להתבטא בשינוי התנהגות."]},{"h":"שברים בפנים","steps":false,"items":["שבר דחוס: חלקי עצם נכנסים פנימה ועלולים לפגוע במוח.","שבר בעצם הלחי עלול לכלוא שרירי עין ולהגביל את תנועת העין.","שבר בלסת: סכנה לחסימת נתיב האוויר.","שבר בבסיס הגולגולת: עיני דביבון, סימן באטל מאחורי האוזן, ונוזל דמי מהאוזניים או מהאף."]}],"quiz":[["למה דימום בתוך הגולגולת מעלה לחץ על המוח?",["כי לגולגולת אין מקום להתרחב","כי הגולגולת רכה","כי הדם יוצא החוצה","הוא לא מעלה לחץ"],"הנפח קבוע, וכל תוספת לוחצת על המוח."],["מה התפקיד של נוזל השדרה?",["לבודד, לתמוך ולהזין את המוח ואת חוט השדרה","להעביר חמצן לשרירים","לייצר דם","לסנן אוויר"],"הוא זורם בחלל התת-עכבישי."],["בשבר בעצם הלחי המטופל לא מצליח להזיז עין למעלה. למה?",["שריר העין נכלא בשבר","זה תמיד שבץ","זו אלרגיה","זה תקין"],"שבר ברצפת ארובת העין יכול ללכוד שרירים."],["מהי פגיעת 'קונטר-קו' (מכה נגדית)?",["פגיעה במוח בצד הנגדי לנקודת המכה","פגיעה רק בעור","שבר בלסת","דימום מהאף"],"המוח נהדף לאחור ונחבט בדופן השנייה."],["אילו שלושה קרומים עוטפים את המוח?",["דורה, ארכנואיד ופיה","פלאורה, פריטונאום ופריקרד","עור, שומן ושריר","אין קרומים"],"הדורה היא החיצונית והקשה."]],"images":[["head-neck--3-4-p-004-019.webp","שכבות הקרקפת מעל הגולגולת"],["head-neck--3-4-p-007-031.webp","קרומי המוח: דורה, ארכנואיד ופיה"],["head-neck--3-4-p-012-049.webp","מנגנון האצה-האטה: המוח פוגע בדופן הגולגולת"],["head-neck--3-4-p-013-052.webp","עיני דביבון: סימן לשבר בבסיס הגולגולת"],["head-neck--3-4-p-017-069.webp","דימום ונוזל מהאף ומהאוזן בשבר בבסיס הגולגולת"],["head-neck--3-4-p-018-073.webp","סימן באטל: שטף דם מאחורי האוזן"],["head-neck--3-4-p-021-082.webp","דימום בתוך הגולגולת"],["head-neck--3-4-p-029-103.webp","קיבוע ידני של הראש"]]},"chest":{"learn":[{"h":"חבישת חזה עם שסתום","steps":true,"items":["מייבשים היטב את העור סביב הפצע.","מקלפים את הגב של המדבקה, מותחים ומניחים כשהשסתום מעל הפצע.","השסתום מאפשר לאוויר ולדם לצאת ומונע מהם להיכנס.","בלי חבישה ייעודית: חבישה אטומה שסגורה רק מ-3 צדדים.","אם המצב מתדרדר: מסירים את החבישה כדי לשחרר לחץ."]},{"h":"עוד דגשים","steps":false,"items":["צלעות 1-2 שבורות מעידות על עוצמה גדולה; צלעות 8-12 מחשידות לפגיעה בכבד, בטחול ובכליות.","בשבר בצלעות מעודדים את הנפגע לנשום כרגיל למרות הכאב, ושוקלים סיוע נשימתי.","חזה אוויר סגור יכול לקרות גם בלי חבלה, אצל חולי ריאה או אצל צעירים רזים.","נפגע בהכרה שמתקשה לנשום: מושיבים בתנוחה הנוחה לו, בהתחשב בחשד לפגיעה בעמוד השדרה."]}],"quiz":[["למה בחבישת חזה יש שסתום?",["כדי לתת לאוויר לצאת בלי לתת לו להיכנס","כדי לנשום דרכו","כדי להזרים חמצן","אין סיבה"],"זה מונע התפתחות חזה אוויר בלחץ."],["אחרי חבישת חזה המצב מתדרדר. מה עושים?",["מסירים את החבישה כדי לשחרר לחץ","מוסיפים עוד חבישה","מהדקים חזק","לא עושים כלום"],"ייתכן שהצטבר לחץ מתחת לחבישה."],["אין חבישת חזה ייעודית. מה עושים?",["חבישה אטומה סגורה מ-3 צדדים","משאירים את הפצע פתוח","סוגרים מכל 4 הצדדים","שמים גזה רטובה"],"הצד הפתוח מתפקד כשסתום."],["מה עושים לפני הדבקת חבישת חזה?",["מייבשים היטב את העור","מורחים משחה","מגלחים את כל החזה","שוטפים במים"],"על עור רטוב החבישה לא נדבקת."],["איך מטפלים בנפגע עם שבר בצלע שכואב לו לנשום?",["מעודדים לנשום כרגיל ומעריכים שוב","קושרים את בית החזה חזק","אוסרים עליו לדבר","משכיבים על הבטן"],"נשימה שטחית מגבירה סיכון לסיבוכים."]],"images":[["chest--3-5-p-004-019.webp","הריאות, הלב וקרומי הפלאורה בבית החזה"],["chest--3-5-p-008-032.webp","שברים בצלעות"],["chest--3-5-p-009-036.webp","חזה מרפרף: מקטע צלעות שבור בשני מקומות"],["chest--3-5-p-012-046.webp","חזה אוויר (פנאומוטורקס) סגור ופתוח"],["chest--3-5-p-015-057.webp","חזה אוויר בלחץ: לחץ דוחק את הלב ואת הריאה השנייה"],["chest--3-5-p-018-066.webp","חזה אוויר, חזה דם, ושילוב של שניהם"],["chest--3-5-p-020-073.webp","חבישה אוטמת (חזה) על פצע פתוח בבית החזה"],["chest--3-5-p-021-079.webp","טמפונדה: דם בשק הלב לוחץ על הלב"],["chest--3-5-p-023-086.webp","שלבי קרע (דיסקציה) באאורטה"]]},"abdomen":{"learn":[{"h":"איך מטפלים ביציאת איברים","steps":true,"items":["לא מחזירים את האיברים פנימה.","מכסים בפד סטרילי לח (סליין), כדי שלא יתייבשו.","מעל הפד שמים כיסוי אטום (ניילון) ושומרים על חום.","לא מפעילים לחץ על האיברים.","מפנים בדחיפות, בלי אוכל ושתייה."]},{"h":"עוד דגשים","steps":false,"items":["יכולת האבחון בשטח מוגבלת, ולעיתים הקינמטיקה היא הרמז היחיד לפגיעה בבטן.","פגיעה באיבר חלול שופכת תוכן לבטן וגורמת לפריטוניטיס ולספסיס.","לחץ פתאומי מחגורת בטן יכול לקרוע את שלפוחית השתן, את המעי הגס ואת החלחולת.","חבלה חזקה יכולה לקרוע את הסרעפת."]}],"quiz":[["מעיים יצאו מפצע בבטן. מה עושים?",["מכסים בפד סטרילי לח ובניילון, בלי להחזיר","מחזירים אותם פנימה","מכסים בגזה יבשה ולוחצים","שוטפים במים מהברז ומחזירים"],"מונעים התייבשות ונזק נוסף."],["למה לא נותנים לנפגע בטן לאכול ולשתות?",["כי ייתכן ניתוח ופגיעה במערכת העיכול","כי זה מחמם","כי אין זמן","זה מותר"],"אוכל ושתייה מסכנים בניתוח ועלולים להחמיר."],["מה עלול לקרות כשתוכן המעי נשפך לבטן?",["פריטוניטיס וספסיס","שום דבר","שבר באגן","שבץ"],"זיהום חמור של חלל הבטן."],["מה עשוי להיות הרמז היחיד לפגיעת בטן בשלב הראשון?",["הקינמטיקה","צבע הבגדים","הגיל בלבד","מזג האוויר"],"לכן קוראים את הזירה."]],"images":[["abdomen--3-6-p-003-015.webp","איברי הבטן: איברים חלולים ואיברים מלאים"],["abdomen--3-6-p-008-036.webp","הכבד והטחול מוגנים חלקית בידי הצלעות"],["abdomen--3-6-p-012-048.webp","האגן ועצמותיו"],["abdomen--3-6-p-015-056.webp","יציאת מעיים (אוויסצרציה)"],["abdomen--3-6-p-016-064.webp","הרטבת פד סטרילי בסליין לפני כיסוי המעיים"],["abdomen--3-6-p-016-066.webp","כיסוי המעיים בפד לח ובניילון, בלי להחזיר אותם פנימה"]]},"skeletal":{"learn":[{"h":"העצם רקמה חיה","steps":false,"items":["העצם מקבלת אספקת דם קבועה, ובנויה מסיבי חלבון שנותנים גמישות ומסידן שנותן קשיות.","עם הגיל יש פחות חלבון ופחות סידן, והעצמות נעשות שבירות יותר.","שבר יכול לפגוע גם בכלי הדם, בעצבים וברקמות סביבו.","גיד מחבר שריר לעצם. הוא חזק ולא אלסטי, ויכול אפילו לתלוש חלק מהעצם."]},{"h":"פריקה ונקע","steps":false,"items":["נקע: מתיחה או קרע של הרצועות בגלל תנועה חזקה מדי של המפרק.","פריקה חלקית: העצם יוצאת חלקית מהמפרק ועדיין מוחזקת.","פריקה מלאה: העצם יוצאת לגמרי, והמפרק נתקע בזווית חריגה.","הסימנים דומים לשבר, ופגיעה במפרק יכולה להיות גם שבר. רק רופא שולל שבר."]},{"h":"עבודה עם סד SAM","steps":true,"items":["בונים ומעצבים את הסד על הגפה הבריאה, לא על הפגועה.","מקפלים לצורת C או T כדי שיהיה קשיח.","מוסיפים ריפוד במפרקים ובאזור השבר.","מצמידים בתחבושת אלסטית (או מיקרופור או ניילון נצמד).","לא מתאים? מורידים ומעצבים מחדש."]}],"quiz":[["על איזו גפה מעצבים את סד ה-SAM?",["על הגפה הבריאה","על הגפה הפגועה","על הגב","לא מעצבים"],"כך לא מזיזים את האזור הפגוע."],["למה מקפלים את סד ה-SAM לצורת C?",["כדי שיהיה קשיח","כדי שיהיה קצר","כדי שיהיה רך","כדי לחסוך מקום"],"הקיפול נותן לו את היציבות."],["מה ההבדל בין פריקה מלאה לפריקה חלקית?",["במלאה העצם יצאה לגמרי מהמפרק","אין הבדל","במלאה אין כאב","בחלקית העצם שבורה"],"בפריקה מלאה המפרק נתקע בזווית חריגה."],["מי שולל שבר?",["רק רופא","החובש","המטופל","המשפחה"],"בשטח מתייחסים לכל חשד כשבר."],["למה עצמות של קשישים שבירות יותר?",["כי יש בהן פחות חלבון ופחות סידן","כי הן רכות יותר","כי הן גדולות יותר","הן לא שבירות יותר"],"גמישות וקשיות שתיהן יורדות עם הגיל."]],"images":[["skeletal--3-7-p-004-017.webp","מבנה עצם ארוכה"],["skeletal--3-7-p-006-024.webp","סוגי מפרקים בגוף"],["skeletal--3-7-p-011-042.webp","סוגי שברים: רוחבי, אלכסוני, ספירלי, מרוסק ועוד"],["skeletal--3-7-p-010-038.webp","עיוות בגפה: סימן לשבר"],["skeletal--3-7-p-014-055.webp","דרגות נקע בקרסול"],["skeletal--3-7-p-015-059.webp","פריקה של הכתף בצילום"],["skeletal--3-7-p-023-083.webp","קיפול סד SAM לחיזוק"],["skeletal--3-7-p-029-104.webp","קיבוע אמה בסד SAM, שלב אחר שלב"],["skeletal--3-7-p-034-123.webp","קיבוע קרסול בסד SAM"],["skeletal--3-7-p-020-072.webp","משולש בד לקיבוע הזרוע"]]},"spine":{"learn":[{"h":"מבנה","steps":false,"items":["33 חוליות בצורת S, ובין החוליות דיסקים עם מרכז דמוי ג'ל שבולמים זעזועים.","לחץ גדול יכול לגרום לדיסק לפרוץ וללחוץ על עצבים.","חוט השדרה עובר בתעלה שבמרכז החוליות, מוקף בנוזל השדרה.","יכולת ההתחדשות של מערכת העצבים קטנה, ולכן נזק יכול להיות בלתי הפיך."]},{"h":"מתי מקבעים (PHTLS)","steps":false,"items":["פעם קיבעו כל נפגע טראומה; היום מחליטים לפי עקרונות.","מקבעים כשאי אפשר לסמוך על תלונות הנפגע: שינוי הכרה, השפעת אלכוהול או סמים, פציעה אחרת שמסיחה את הדעת, או קושי בתקשורת.","מקבעים גם כשיש סימנים: כאב או רגישות בעמוד השדרה, חוסר תחושה או חולשה בגפיים.","נפגע שעומד והולך לא בהכרח בלי פגיעה בעמוד השדרה.","בודקים תנועה ותחושה בכל הגפיים לפני הקיבוע ואחריו."]},{"h":"בטיחות בחילוץ מרכב","steps":false,"items":["קוראים לכיבוי לחילוץ, ובלילה דואגים לתאורה.","שמים לב לדלק, שמן ועשן, לזכוכיות ולמוטות מתכת.","לא מחלצים מרכב שנוטה על הצד עד שהוא מיוצב.","ברכב חשמלי יש דגשי בטיחות מיוחדים."]}],"quiz":[["נפגע שתוי אחרי תאונה אומר שאין לו כאב בגב. מקבעים?",["כן, אי אפשר לסמוך על תלונותיו","לא, הוא אמר שאין כאב","רק אם הוא מבקש","רק בילדים"],"אלכוהול הוא גורם שמונע לסמוך על הבדיקה."],["נפגע הולך ומדבר אחרי תאונה. האם זה שולל פגיעה בעמוד השדרה?",["לא","כן, תמיד","כן, אם אין דם","רק אם הוא צעיר"],"שבר יכול להיות יציב עד תזוזה לא זהירה."],["מה בודקים לפני קיבוע ואחריו?",["תנועה ותחושה בגפיים","רק דופק","רק אישונים","את הבגדים"],"כל שינוי מדווחים לבית החולים."],["רכב נוטה על הצד ובתוכו נפגע. מה עושים?",["לא מחלצים עד שהרכב מיוצב","מחלצים מיד","מטפסים על הרכב","מושכים את הנפגע החוצה"],"בטיחות הצוות קודמת."],["ניתוק חוט השדרה בין C1 ל-C5 מסוכן כי:",["הנפגע לא יוכל לנשום לבד","הוא יאבד את הראייה","הוא יאבד רק תחושה ברגליים","אין סכנה מיוחדת"],"העצבים שמפעילים את הסרעפת יוצאים בגובה הזה."]],"images":[["spine--3-8-p-003-015.webp","עמוד השדרה: צווארי, חזי, מותני, עצה וזנב"],["spine--3-8-p-006-025.webp","חוליה, דיסק וחוט השדרה העובר בתעלה"],["spine--3-8-p-008-033.webp","שבר בחוליה"],["spine--3-8-p-009-038.webp","מנגנון צליפת שוט (Whiplash) בצוואר"],["spine--3-8-p-020-061.webp","תרשים החלטה: חשד לפגיעת עמוד שדרה"],["spine--3-8-p-025-077.webp","ילד במושב בטיחות: חילוץ עם המושב"]]},"adjunct":{"learn":[{"h":"שלוש שכבות העור","steps":false,"items":["אפידרמיס: השכבה החיצונית, תאים שמתחלקים ונדחפים למעלה ומתים; עוביה תלוי בחיכוך.","דרמיס: עשירה בכלי דם, עצבים, זקיקי שיער ובלוטות זיעה וחלב, ובה תאי הגנה.","תת-עור: רקמת שומן שסופגת אנרגיה ושומרת על חום הגוף."]},{"h":"סוגי פצעים","steps":false,"items":["שפשוף (אברזיה): פגיעה שטחית; בשטח גדול מסוכן לזיהום ומתנהג כמו כוויה.","חתך או קרע: שוליים ישרים או משוננים, לפי הגורם.","דקירה: פתח קטן ונזק עמוק שלא נראה מבחוץ.","חבלה (שטף דם): דם יוצא לרקמות, אדום ואחר כך כהה.","פצע יכול להיראות דרמטי ועדיין לא להיות הסכנה העיקרית; לא מעכבים פינוי של נפגע לא יציב בשביל חבישות."]},{"h":"דימום מהאף ומהפה","steps":true,"items":["מטים את הראש קדימה (לא לאחור), כדי שהדם לא ייבלע.","לוחצים על החלק הרך של האף, צמוד לעצם.","דימום מהפה בדרך כלל נעצר לבד; אפשר לעזור בחפץ קר שאינו רעיל.","חבלה בעין: מכסים את שתי העיניים ומפנים בישיבה אם אין מניעה."]}],"quiz":[["דימום מהאף. לאן מטים את הראש?",["קדימה","אחורה","הצידה","לא מזיזים"],"הטיה לאחור גורמת לבליעת דם ולהקאה."],["איפה לוחצים בדימום מהאף?",["על החלק הרך של האף, צמוד לעצם","על המצח","על הגשר העליון של האף","על השפה"],"לחיצה על הכנפיים הרכות סוגרת את כלי הדם."],["מה מאפיין פצע דקירה?",["פתח קטן ונזק עמוק","פצע רחב ושטחי","תמיד דימום חזק מבחוץ","תמיד בלי סכנה"],"מראה הפצע לא משקף את הנזק."],["איזו שכבת עור עשירה בכלי דם ועצבים?",["הדרמיס","האפידרמיס","השיער","הציפורניים"],"מתחת לאפידרמיס."],["למה שפשוף בשטח גדול מסוכן?",["סכנת זיהום, והוא מתנהג כמו כוויה","הוא תמיד מדמם חזק","הוא גורם לשבר","אין סכנה"],"השכבה העליונה שמגינה חסרה."]],"images":[["adjunct--3-9-p-004-025.webp","שכבות העור"],["adjunct--3-9-p-011-056.webp","שפשוף (אברזיה)"],["adjunct--3-9-p-013-069.webp","חתך (לצרציה)"],["adjunct--3-9-p-015-087.webp","פצע תלוש (אבולסיה)"],["adjunct--3-9-p-016-101.webp","פצע דקירה: פתח קטן ונזק עמוק"],["adjunct--3-9-p-018-111.webp","חפץ חודר בכף הרגל בצילום"],["adjunct--3-9-p-021-136.webp","קיבוע חפץ חודר במקומו בעזרת תחבושות"],["adjunct--3-9-p-030-183.webp","כוויה בדרגה שנייה: שלפוחיות"],["adjunct--3-9-p-031-187.webp","כוויה בדרגה שלישית: כל עובי העור"],["adjunct--3-9-p-028-171.webp","שלפוחיות בכוויה בדרגה שנייה"],["adjunct--3-9-p-034-205.webp","כלל התשעיות להערכת שטח כוויה במבוגר, בילד ובתינוק"],["adjunct--3-9-p-027-165.webp","כוויה ממים רותחים: גורם נפוץ בבית"]]},"drowning":{"learn":[{"h":"מה קורה בטביעה","steps":false,"items":["מים בדרכי האוויר גורמים לעיתים לעווית בגרון (לרינגוספזם), ורק במיעוט המקרים היא סוגרת לגמרי.","החמצון והאוורור נפגעים, ונוצרת היפוקסיה.","רפלקס הבליעה ממשיך לפעול זמן מה אחרי אובדן ההכרה, ולכן הקיבה מתמלאת מים וסכנת ההקאה גבוהה."]},{"h":"דגשי טיפול","steps":false,"items":["חילוץ רק בידי מי שמיומן בכך; בטיחותך קודמת.","בכל אפשרות לפגיעה (קפיצה למים רדודים, גלים) מתייחסים לטובע כחשוד בפגיעת עמוד שדרה צווארי.","שואבים הפרשות נראות, ומכסים את הנפגע למניעת היפותרמיה.","גם מי שנראה בסדר מפנים למעקב, כי סיבוכים בריאות יכולים להופיע מאוחר יותר.","החייאה עם דפיברילטור: מתרחקים מהמים ומשפת הבריכה, ולא נוגעים בזמן השוק."]}],"quiz":[["למה טובע מחוסר הכרה בסיכון גבוה להקאה?",["כי רפלקס הבליעה ממשיך ומכניס מים לקיבה","כי הוא אכל לפני","כי המים מלוחים","אין סיכון כזה"],"לכן נערכים לשאיבה ולהטיה על הצד."],["טובע שהתאושש ונראה בסדר. מה עושים?",["מפנים למעקב בבית חולים","משחררים הביתה","נותנים לו לשחות שוב","נותנים לו אוכל"],"סיבוכים ריאתיים יכולים להתפתח מאוחר."],["מתי חושדים בפגיעת צוואר בטובע?",["כשיש אפשרות לחבלה, למשל קפיצה למים רדודים","אף פעם","רק בילדים","רק בים"],"מקבעים ידנית ומזיזים בזהירות."]],"images":[["drowning--3-10-p-003-015.webp","טובע אמיתי: ראש נמוך במים, ידיים מכות במים, בלי קריאה לעזרה"],["drowning--3-10-p-008-030.webp","חילוץ מהמים בידי מצילים"],["drowning--3-10-p-010-036.webp","טיפול בנפגע טביעה על החוף"]]},"electrical":{"learn":[{"h":"מה עושה החשמל","steps":false,"items":["הזרם עובר בגוף ופוגע בלב (הפרעות קצב), במערכת העצבים ובשרירים.","החום יוצר חור כניסה וחור יציאה, ובפנים יכולות להיות כוויות עמוקות שלא נראות מבחוץ.","התכווצות שרירים חזקה יכולה לגרום לשברים, והנפגע עלול ליפול או להיזרק.","כשליש מנפגעי מתח גבוה (1,000 וולט ומעלה) צריכים החייאה; התחשמלות בבית בדרך כלל פחות מסוכנת."]},{"h":"טיפול","steps":true,"items":["מנתקים את זרם החשמל; אם אין גישה למתג, משתמשים בחומר שאינו מוליך.","נפגע שכבר לא מחובר למקור לא מחשמל, ומותר לגעת בו.","בהחייאה מחברים דפיברילטור מוקדם, כי הפרעות קצב שכיחות.","מחפשים חור כניסה ויציאה, שברים ופגיעות מנפילה, ומקבעים לפי הצורך."]}],"quiz":[["מה הצעד הראשון בהתחשמלות?",["לנתק את זרם החשמל","לגעת בנפגע ולמשוך אותו","לשפוך עליו מים","להתחיל עיסויים מיד"],"בלי ניתוק אתה הנפגע הבא."],["אין גישה למתג. איך מרחיקים את הנפגע מהמקור?",["בעזרת חומר שאינו מוליך, כמו עץ יבש","ביד חשופה","במוט מתכת","במגבת רטובה"],"מים ומתכת מוליכים."],["למה חשוב לחפש חור יציאה?",["כדי להבין את מסלול הזרם והנזק הפנימי","כדי לחבוש רק אותו","אין צורך","כדי לדעת את המתח"],"הנזק העמוק גדול ממה שנראה."],["למה מתחשמל יכול לשבור עצם בלי ליפול?",["בגלל התכווצות שרירים חזקה","בגלל החום","בגלל ההלם","זה לא אפשרי"],"השרירים מתכווצים בעוצמה אדירה."]],"images":[["electrical--3-10-p-012-044.webp","התחשמלות באתר עבודה: קודם ניתוק המקור, אחר כך מגע"]]},"environmental":{"learn":[{"h":"איך הגוף שומר על חום","steps":false,"items":["הטווח התקין הוא 36.5-37.5 מעלות; סטייה של 2 מעלות פוגעת בתפקוד.","בחום: הזעה, הרחבת כלי דם בעור והפחתת ייצור חום.","בקור: רעד, כיווץ כלי דם בעור והפעלת שרירים.","קשישים ותינוקות רגישים במיוחד, גם בגלל תרופות ושתייה מעטה."]},{"h":"התייבשות: מה עושים","steps":true,"items":["משכיבים במנוחה במקום מוצל.","קלה או בינונית, ואין הקאות: שתייה מתוקה ומגוונת, בכמויות קטנות ורצופות.","מקיא: לא נותנים לשתות, כי מערכת העיכול לא עובדת כרגיל ויש סכנת שאיפה.","שוקלים עירוי בלי לעכב פינוי."]},{"h":"היפותרמיה: מה עושים","steps":true,"items":["מרחיקים מהסביבה הקרה, מייבשים ומכסים (שמיכת מילוט).","משכיבים בעדינות ונמנעים מתזוזות, כי לב קר רגיש להפרעות קצב.","סבב ABC ובדיקת סוכר.","שוקלים עירוי נוזלים מחוממים."]}],"quiz":[["נפגע מיובש מקיא. נותנים לו לשתות?",["לא, יש סכנת הקאות ושאיפה","כן, הרבה ומהר","כן, רק מים קרים","כן, משקה אלכוהולי"],"מקיא לא שותה; שוקלים עירוי."],["למה מזיזים נפגע היפותרמי בעדינות?",["כי לב קר רגיש להפרעות קצב","כדי שלא יתעורר","כי הוא כבד","אין סיבה"],"תזוזה חדה יכולה לגרום לפרפור חדרים."],["מהו טווח חום הגוף התקין?",["36.5-37.5","35-36","38-39","34-35"],"סטייה של 2 מעלות כבר פוגעת בתפקוד."],["מהי שמיכת מילוט?",["שמיכה דקה ששומרת על חום הגוף בתנאי קור","שמיכה לקירור","שמיכה רטובה","שמיכת צמר כבדה"],"נמצאת בציוד ומשמשת למניעת היפותרמיה."]],"images":[["environmental--3-11-p-005-021.webp","איך הגוף מאבד חום: קרינה, הולכה, הסעה ואידוי"],["environmental--3-11-p-007-031.webp","מכת חום: חולשה, כאב ראש וחום גבוה"],["environmental--3-11-p-018-059.webp","היפותרמיה: רעד וקור"],["environmental--3-11-p-022-071.webp","קירור נפגע מכת חום בשטח"],["environmental--3-11-p-025-082.webp","כוויות קור באצבעות"]]},"bites":{"learn":[{"h":"נחשים ארסיים בישראל","steps":false,"items":["בכל שנה יש 200-300 הכשות, וכ-95% מהן של צפע ארץ ישראלי.","צפע ארץ ישראלי: עד 135 ס\"מ, אוהב לגור ליד בני אדם, והכשתו עלולה להמית.","אפעה: מדברי, עד 80 ס\"מ, ראש משולש בולט.","צפע חרמון חי רק בחרמון; עכן גדול ועכן קטן חיים בחולות הדרום ומתקדמים בזחילה הצידה.","שפיפון: עם 'קרניים' קטנות מעל העיניים; פתן: מכיש בשן אחת בתנועת ראש הצידה.","אי אפשר לזהות בוודאות נחש ארסי לפי צורת הראש; מתייחסים לכל הכשה כארסית."]},{"h":"עקרבים ועכבישים","steps":false,"items":["בישראל 24 מיני עקרבים. המסוכנים: עקרב צהוב מצוי (עד 11.5 ס\"מ), קטלן דו-גוני וקטלן עב-זנב.","יש רק שני עכבישים מסוכנים בישראל: ששן חום (6 עיניים, מתחבא במחסנים ומאחורי מכונות כביסה) ואלמנה שחורה.","הרבה עקיצות של עכבישים קורות כשהעכביש מסתתר בבגד ונושך כשלובשים אותו."]},{"h":"כלבת","steps":false,"items":["מועברת ברוק של בעל חיים נגוע, בעיקר בנשיכה.","בתקופת הדגירה אפשר לעצור את הנגיף בטיפול; אחרי שהגיע למערכת העצבים המחלה קטלנית.","לכן כל נשיכה מופנית מיד להמשך טיפול, במיוחד מכלב לא מזוהה."]}],"quiz":[["איזה נחש אחראי לרוב ההכשות בישראל?",["צפע ארץ ישראלי","אפעה","פתן","עכן קטן"],"כ-95% מהמקרים."],["אפשר לזהות נחש ארסי בוודאות לפי צורת הראש?",["לא, מתייחסים לכל הכשה כארסית","כן, תמיד","כן, לפי הצבע","כן, לפי האורך"],"לא לבזבז זמן על זיהוי."],["איפה נוטה להסתתר ששן חום?",["במקומות שקטים וחמים, כמו מחסנים ומאחורי מכונות כביסה","בים","על עצים","במים מתוקים"],"פעיל בעיקר בחושך."],["למה כל נשיכה של כלב לא מזוהה מופנית לטיפול?",["בגלל סכנת כלבת, שהופכת קטלנית אחרי הופעת הסימנים","בגלל הכאב בלבד","בגלל הדימום בלבד","אין צורך"],"בתקופת הדגירה אפשר לעצור את הנגיף."],["כמה מיני עקרבים יש בישראל?",["24","3","100","1,750"],"1,750 בעולם, 24 בישראל."]],"images":[["bites--3-12-p-015-085.webp","צפע ארץ ישראלי: הנחש הארסי הנפוץ בארץ"],["bites--3-12-p-016-091.webp","אפעה"],["bites--3-12-p-018-103.webp","עכן גדול"],["bites--3-12-p-019-109.webp","פתן"],["bites--3-12-p-033-168.webp","סימני הכשה: נחש ארסי משאיר שני חורי ניבים"],["bites--3-12-p-025-141.webp","עקרב צהוב מצוי"],["bites--3-12-p-026-144.webp","קטלן דו-גוני"],["bites--3-12-p-029-154.webp","ששן חום"],["bites--3-12-p-030-158.webp","אלמנה שחורה"],["bites--3-12-p-031-162.webp","נדל"],["bites--3-12-p-036-185.webp","מדוזה"],["bites--3-12-p-039-216.webp","צריבת מדוזה על הרגל"],["bites--3-12-p-040-221.webp","טיפול בצריבת מדוזה: שטיפה במי ים והוצאת שאריות"],["bites--3-12-p-046-249.webp","זהרון הדור: קוצים ארסיים"],["bites--3-12-p-051-271.webp","עוקץ של דבורה נשאר בעור"],["bites--3-12-p-053-284.webp","הוצאת העוקץ בגירוד הצידה, בלי ללחוץ על שק הארס"],["bites--3-12-p-052-280.webp","מזרק אדרנלין (אפיפן) למטופל אלרגי"]]},"abdominal-emerg":{"learn":[{"h":"גבולות חלל הבטן והצפק","steps":false,"items":["למעלה הסרעפת, למטה עצמות האגן, מאחור עמוד השדרה ושרירי הגב, ומלפנים קיר הבטן.","רוב האיברים נמצאים בתוך קרום הצפק (פריטונאום), חלל סטרילי ורגיש.","דם, נוזלי גוף או הפרשות שנכנסים לצפק גורמים לדלקת ולכאב חזק.","הכליות נמצאות מאחורי הצפק (רטרופריטונאלי)."]},{"h":"תפקידי האיברים בקצרה","steps":false,"items":["הכבד מייצר מרה לעיכול שומנים, חלבונים וגורמי קרישה; כיס המרה אוגר את המרה.","הלבלב מפריש אנזימי עיכול ואינסולין.","המזון נספג במעי הדק, והפסולת עוברת במעי הגס לחלחולת.","הכליות מסננות דם, מווסתות לחץ דם ושומרות על מאזן נוזלים ומלחים; השתן עובר בשופכנים לשלפוחית ומשם בשופכה החוצה.","הווריד הנבוב התחתון הוא הווריד הגדול בבטן, ומחזיר דם ללב."]}],"quiz":[["מה קורה כשדם נכנס לחלל הצפק?",["דלקת וכאב חזק בבטן","שום דבר","הקלה בכאב","חום גוף נמוך"],"הצפק סטרילי ורגיש מאוד."],["איפה נמצאות הכליות?",["מאחורי הצפק, ליד הגב","בתוך הקיבה","באגן הקדמי","מתחת לסרעפת בחזה"],"לכן כאב כליות מורגש בגב ובמותן."],["מה מייצר הכבד?",["מרה, חלבונים וגורמי קרישה","אינסולין","שתן","רוק"],"פגיעה בכבד פוגעת גם בקרישה."],["מה הגבול העליון של חלל הבטן?",["הסרעפת","עצמות האגן","הצלעות התחתונות בלבד","הטבור"],"מעליה בית החזה."]],"images":[["abdominal-emerg--4-3-p-005-022.webp","ארבעת רבעי הבטן"],["abdominal-emerg--4-3-p-008-033.webp","מערכת העיכול: וושט, קיבה, כבד, לבלב ומעיים"],["abdominal-emerg--4-3-p-012-042.webp","מערכת השתן: כליות, שופכנים ושלפוחית"],["abdominal-emerg--4-3-p-024-080.webp","דלקת התוספתן"],["abdominal-emerg--4-3-p-023-076.webp","כאב ברבע הימני התחתון בדלקת התוספתן"],["abdominal-emerg--4-3-p-029-095.webp","אבנים בכליה"],["abdominal-emerg--4-3-p-027-089.webp","חסימה בדרכי השתן מרחיבה את הכליה"],["abdominal-emerg--4-3-p-022-072.webp","תסמינים: הקאה, כאב בבטן הימנית, חום"]]},"infectious":{"learn":[{"h":"סוגי מחוללי מחלה","steps":false,"items":["חיידקים: מתרבים לבד, אבל צריכים סביבה תומכת; אנטיביוטיקה פועלת נגדם.","נגיפים (וירוסים): מתרבים רק בתוך תאים, ואנטיביוטיקה לא עוזרת נגדם.","פטריות ותולעים, ופתוגנים 'מזדמנים' שמסוכנים בעיקר לאנשים עם מערכת חיסון חלשה."]},{"h":"דלקות כבד נגיפיות","steps":false,"items":["הפטיטיס A: עוברת בצואה נגועה דרך הפה (מזון ומים); יש חיסון, חולים רק פעם אחת, ולרוב עוברת בלי סיבוכים.","הפטיטיס B: עוברת בדם ובנוזלי גוף, מדבקת גם כשהחולה מרגיש טוב, ואצל חלק הופכת לכרונית; יש חיסון.","הפטיטיס C: עוברת בעיקר בדם, ובחלק גדול מהחולים הופכת לכרונית."]},{"h":"אחרי חשיפה","steps":true,"items":["מוודאים שהייתה חשיפה ומתמגנים.","מאווררים את מקום הטיפול.","בודקים לאן פונה החולה ומעדכנים את צוות המלר\"ד.","מדווחים מיד למנהל אגף רפואה בארגון.","מגיעים לרופא או למיון בהקדם וממשיכים מעקב."]}],"quiz":[["למה אנטיביוטיקה לא עוזרת נגד וירוסים?",["כי הם מתרבים בתוך התאים","כי הם גדולים מדי","כי הם חיידקים","היא כן עוזרת"],"אנטיביוטיקה פועלת על חיידקים."],["איך עוברת הפטיטיס A?",["בצואה נגועה דרך הפה, במזון ובמים","רק בדם","בנשיכת יתוש","במגע בעור"],"לכן היגיינה וחיסון מונעים אותה."],["הפטיטיס B מדבקת גם כשהחולה מרגיש טוב?",["כן","לא","רק בחורף","רק בילדים"],"לכן כל דם מטופל כמדבק."],["אחרי טיפול בחולה עם מחלה מדבקת, מה עושים עם הציוד המתכלה?",["בשקית נפרדת וסגורה להשמדה, לא לפח רגיל","לפח רגיל","שוטפים ומשתמשים שוב","משאירים בבית המטופל"],"ציוד רב-פעמי (אמבו, סקשן) רוחצים ומחטאים."],["מה עושים במחט אחרי דקירת מטופל?",["משליכים מיד לפח מחטים בלי להחזיר מכסה","מחזירים את המכסה","מקפלים את המחט","שמים בכיס"],"מפרידים מחט רק בעזרת שולי פח המחטים."]],"images":[["infectious--4-4-p-012-052.webp","כללי בטיחות במחטים: לא מחזירים מכסה, משליכים למכל ייעודי"],["infectious--4-4-p-022-112.webp","דלקת קרום המוח וגורמיה"]]},"special-patient":{"learn":[{"h":"מה משתנה בגוף בזקנה","steps":false,"items":["נשימה: הנשימה נעשית יותר סרעפתית, ומחלות ריאה כרוניות שכיחות יותר; גם החמרה קלה משמעותית.","לב וכלי דם: כלי הדם פחות גמישים, ומחלות לב שכיחות.","מוח: תהליכים איטיים יותר ורפלקסים איטיים, אבל שינוי חד בהכרה הוא סימן לבעיה.","גם תפקוד הכליות, מערכת החיסון, חוש הטעם והריח וצפיפות העצם יורדים."]},{"h":"לפני שמפנים זקן מהבית","steps":false,"items":["מכבים אורות וגז, ומוודאים שהבית נעול.","לוקחים תיק, טלפון ותעודה מזהה, ונעליים אם אינו מסוגל לנעול.","מוודאים שהוא לבוש לפי מזג האוויר.","מנסים ליצור קשר עם בן משפחה שיפגוש אותו בבית החולים."]},{"h":"גישה לילד","steps":false,"items":["מציגים את עצמנו בשם פשוט ושואלים את הילד לשמו.","יושבים לידו בגובה העיניים ומעדכנים את ההורים מהר.","מסבירים מה עושה כל מכשיר לפני שמשתמשים בו.","אם צפוי כאב, אומרים את האמת: שהוא רגעי ולמה הוא נחוץ.","מגיל 12 בערך או מעל 40 ק\"ג מתייחסים כמו למבוגר."]}],"quiz":[["זקן לא מדבר בבירור. מה נכון?",["אין פירוש שהוא לא מבין; מדברים איתו בכבוד ובגובה העיניים","מדברים רק עם המשפחה","צועקים כדי שישמע","לא מסבירים לו כלום"],"לא מזלזלים בהבנה בגלל קושי בתקשורת."],["מה עושים עם ילד לפני הליך שיכאב?",["מסבירים בכנות שהכאב רגעי ולמה הוא נחוץ","אומרים שלא יכאב","לא אומרים כלום","מבקשים מההורים לצאת"],"כנות בונה אמון."],["מאיזה משקל מטפלים כמו במבוגר?",["מעל 40 ק\"ג (בערך מגיל 12)","מעל 20 ק\"ג","מעל 60 ק\"ג","רק מגיל 18"],"ההגדרה לפי גיל ומשקל."],["למה החמרה קלה בנשימה מסוכנת אצל זקן?",["כי הרזרבה הנשימתית שלו קטנה","כי הוא תמיד מגזים","כי זה סימן לאלרגיה","אין סכנה"],"גם שינוי קטן יכול להיות משמעותי."]],"images":[["special-patient--4-5-p-006-020.webp","שינויים בריאות בגיל המבוגר"],["special-patient--4-5-p-021-090.webp","נתיב האוויר בילד: לשון גדולה, קנה צר וגמיש"],["special-patient--4-5-p-026-110.webp","מדידת חום בתינוק"],["special-patient--4-5-p-040-168.webp","מוגבלויות: ראייה, שמיעה, תקשורת ותנועה"]]},"diving":{"learn":[{"h":"ירידה ועלייה","steps":false,"items":["בירידה הלחץ עולה; חלל אוויר שלא משווה לחץ (אוזן, סינוסים, מסכה) יוצר תת-לחץ ששואב דם ונוזלים.","סימנים בירידה: כאב באוזניים ובסינוסים שגובר בהעמקה, צפצופים באוזניים, סימני 'וואקום' בצורת המסכה על הפנים.","בעלייה הגז מתרחב: אם הצולל עוצר נשימה או עולה מהר, הריאה עלולה להיקרע, לרוב ב-5 המטרים האחרונים.","קרע בריאה יכול לגרום לתסחיף אוויר שמגיע למוח, עד אובדן הכרה."]},{"h":"מחלת דקומפרסיה","steps":false,"items":["בעומק מתמוסס יותר חנקן בגוף; בעלייה איטית הוא יוצא בנשימה, ובעלייה מהירה נוצרות בועות.","הסימנים יכולים להופיע מאוחר: עור, כאבי מפרקים, חולשה, נימול ושיתוק, קוצר נשימה וכחלון.","שואלים: האם היה מחשב צלילה וחריגה מתועדת, האם טס אחרי הצלילה, האם עשה צלילות 'יו-יו'.","גורמים מגבירים: אלכוהול, עייפות, קור, מאמץ מתחת למים."]},{"h":"שכרון מעמקים","steps":false,"items":["מתחיל בעומק של כ-30 מטר (4 אטמוספרות), מלחץ החנקן.","הצולל מתנהג כמו שיכור ומאבד שיקול דעת, ועלול לעלות מהר מדי."]}],"quiz":[["באיזה שלב של הצלילה קרע ריאה נפוץ?",["בעלייה, לרוב ב-5 המטרים האחרונים","בירידה","בשהייה בעומק","על החוף"],"הגז מתרחב כשהלחץ יורד."],["למה צולל צריך לנשוף בעלייה?",["כדי שהאוויר המתרחב לא יקרע את הריאות","כדי לרדת מהר","כדי לחסוך אוויר","אין צורך"],"עצירת נשימה בעלייה מסוכנת."],["מאיזה עומק בערך מתחיל שכרון מעמקים?",["30 מטר","5 מטר","100 מטר","מעל המים"],"4 אטמוספרות."],["צולל טס יום אחרי צלילה וקיבל כאבי מפרקים ונימול. מה החשד?",["מחלת דקומפרסיה","שכרון מעמקים","ברוטראומה של האוזן","התייבשות בלבד"],"שינוי גובה מגביר יציאת חנקן כבועות."],["מה מגביר סיכון למחלת דקומפרסיה?",["אלכוהול, עייפות, קור ומאמץ","שינה טובה","שתיית מים","צלילה רדודה וקצרה"],"אלכוהול מרחיב כלי דם ומגביר ספיגת חנקן."]],"images":[["diving--4-6-p-004-016.webp","הלחץ עולה באטמוספרה כל 10 מטר עומק, ונפח הגז קטן"],["diving--4-6-p-005-019.webp","עומק, לחץ ונפח האוויר בריאות"],["diving--4-6-p-006-022.webp","חללי אוויר בגוף שנפגעים מלחץ: סינוסים, אוזן, ריאות"],["diving--4-6-p-010-048.webp","פגיעות לחץ בריאות ותסחיף אוויר"],["diving--4-6-p-018-075.webp","תא לחץ לטיפול במחלת לחץ"],["diving--4-6-p-019-079.webp","סימני ידיים של צוללים"]]},"iv-access":{"learn":[{"h":"מתי מותר לחובש","steps":false,"items":["חובש פותח וריד רק כדי לתת נוזלים, ורק אם זה לא מעכב פינוי.","בלי תנאים נוספים: הלם אנפילקטי, והחייאה עם 3 מטפלים ומעלה.","בהלם היפוולמי או ספטי, לידה פעילה או הכשה: רק אם יש גם שני תנאים יחד, ביניהם זמן הגעה למיון של יותר מ-15 דקות.","מקרה אחר שנראה שצריך נוזלים: מבקשים אישור חריג מהרופא התורן דרך המוקד.","מקסימום 1,000 מ\"ל למבוגר ו-500 מ\"ל לילד; לא לחולה לב ידוע עם אי-ספיקת לב."]},{"h":"בדיקת הנוזל והציוד","steps":false,"items":["סליין 0.9%: תמיסה איזוטונית, הנפוצה בערכות. הרטמן (לקטט רינגר) פחות בשימוש היום.","הנוזל צלול ולא עכור, והשקית שלמה ואטומה.","תאריך תפוגה (EXP); אם רשום רק תאריך ייצור (DOM), בודקים שלא עברו 5 שנים.","ממלאים את הסט עד שאין בועות אוויר, ובודקים גם את תוקף הוונפלון."]}],"quiz":[["מה הכמות המרבית של נוזלים שחובש נותן לילד?",["500 מ\"ל","1,000 מ\"ל","250 מ\"ל","2,000 מ\"ל"],"למבוגר עד 1,000 מ\"ל."],["באיזה מצב חובש פותח עירוי בלי תנאים נוספים?",["הלם אנפילקטי","התייבשות קלה","כאב ראש","שבר באצבע"],"גם החייאה עם 3 מטפלים ומעלה."],["על השקית רשום רק תאריך ייצור. מה בודקים?",["שלא עברו 5 שנים מתאריך הייצור","שום דבר","שהשקית קרה","את הצבע בלבד"],"DOM = תאריך ייצור."],["צעיר מיובש אחרי טיול, לא בהתוויה הרגילה. מה עושים אם נראה שצריך נוזלים?",["מבקשים אישור חריג מהרופא התורן דרך המוקד","פותחים עירוי בלי לשאול","לא עושים כלום","נותנים 2 ליטר"],"חריגה מההתוויות רק באישור רופא."],["למי לא נותנים נוזלים?",["לחולה לב ידוע עם אי-ספיקת לב","לנפגע בהלם","לנפגע בהכשה","לילד מיובש"],"נוזלים עלולים להחמיר בצקת ריאות."],["מהי תמיסת סליין 0.9%?",["תמיסה איזוטונית בריכוז המלחים של הגוף","סוכר","תרופה נגד כאב","דם מלאכותי"],"היא הנפוצה בערכות."]],"images":[["iv-access--4-7-p-012-064.webp","חלקי סט העירוי: דוקר, תא טפטוף, ווסת זרימה ומחבר"],["iv-access--4-7-p-014-073.webp","גדלי ונפלון (G) לפי צבע"],["iv-access--4-7-p-014-074.webp","חלקי הוונפלון"],["iv-access--4-7-p-018-088.webp","ורידי היד והאמה המתאימים לעירוי"],["iv-access--4-7-p-016-080.webp","הנחת חוסם ורידים מעל מקום הדקירה"],["iv-access--4-7-p-019-092.webp","דקירה בזווית נמוכה לתוך הווריד"],["iv-access--4-7-p-020-096.webp","הופעת דם בתא ה-Flashback: הכניסה לווריד הצליחה"],["iv-access--4-7-p-021-101.webp","קידום הצינורית ושליפת המחט"],["iv-access--4-7-p-023-114.webp","קיבוע הוונפלון וחיבור העירוי"],["iv-access--4-7-p-024-119.webp","סיבוכי עירוי: הסתננות, דלקת וזיהום"]]},"documentation":{"learn":[{"h":"למה מתעדים","steps":false,"items":["רפואית: התיעוד מאפשר לצוותים הבאים לטפל ברצף ולעקוב אחרי שינויים.","משפטית: הרשומה היא הראיה למה שנעשה. בלי תיעוד, נטל ההוכחה יכול לעבור למטפל.","בתביעת רשלנות צריך להוכיח: התרשלות, חובת זהירות כלפי הנפגע, וקשר סיבתי בין ההתרשלות לנזק.","גם חובשים נושאים באחריות מקצועית, והם נבחנים לפי מה שמצופה מחובש סביר."]},{"h":"האפליקציה","steps":false,"items":["כניסה עם תעודת זהות מלאה (9 ספרות) וקוד בן 4 ספרות שנשלח בוואטסאפ או במייל.","אירועים: תיעוד אירועים ואירועים שהוזנקת אליהם.","גם התנדבויות, שיבוץ משמרות, השתלמויות, אלפון ואזור אישי.","אפשר להגדיר התראות וצליל לאירועים בקרבתך."]}],"quiz":[["מה צריך להוכיח בתביעת רשלנות?",["התרשלות, חובת זהירות וקשר סיבתי לנזק","רק שהיה נזק","רק שהמטפל היה עייף","שהמטופל לא שילם"],"שלושת התנאים יחד."],["לפי מה נבחנת התרשלות של חובש?",["לפי מה שמצופה מחובש סביר","לפי מה שמצופה מרופא","לפי דעת המשפחה","לא נבחנת"],"כל בעל מקצוע לפי הסטנדרט שלו."],["איך נכנסים לאפליקציית התיעוד?",["תעודת זהות וקוד בן 4 ספרות שנשלח בוואטסאפ או במייל","שם משתמש וסיסמה בלבד","טביעת אצבע בלבד","אין צורך בכניסה"],"הקוד נשלח לפרטים השמורים בארגון."],["מה קורה כשאין תיעוד רפואי נאות ויש תביעה?",["נטל ההוכחה יכול לעבור למטפל","זה לא משנה","התביעה נדחית אוטומטית","המטופל מפסיד תמיד"],"התיעוד מגן גם על המטפל."]],"images":[]},"mci":{"learn":[{"h":"מתי זה אר\"ן","steps":false,"items":["אין מספיק כוחות לטפל מיד בכל הנפגעים.","צריך לתעדף נפגעים (טריאז') לפי חומרת הפציעה וסיכויי ההישרדות.","המשאבים הנדרשים (כוח אדם וציוד) חורגים מהשגרה.","תרחישים: תאונה גדולה (אוטובוס, רכבת, הרבה רכבים), פיגוע, נזקי טבע כמו רעידת אדמה."]},{"h":"שלושת מעגלי המענה","steps":false,"items":["מעגל I (פנימי): המגיבים הראשונים בזירה, כמו איחוד הצלה ומד\"א.","מעגל II (אמצעי): כוחות רפואה נוספים בשטח, כמו צה\"ל.","מעגל III (חיצוני): בתי חולים רחוקים ומשרד הבריאות.","איחוד הצלה: כ-8,000 מתנדבים, מגיבים ראשונים, מסייעים למד\"א שמנהל את הזירה בתוך הקו הירוק."]},{"h":"כונן באר\"ן: מה עושים בקשר","steps":true,"items":["מקשיבים לגל ומחכים לתמונת מצב מהמוקד.","אם אתה קרוב לפי הגדרות המרחק והזמן, מדווח יציאה בלבד: מספר כונן ו'בדרך לאר\"ן'.","שומרים על 'גל נקי': לא שואלים פרטים מיותרים.","מגיעים בבטחה ומתייצבים לפי הנחיות הצלה 10."]}],"quiz":[["מה מבין אלה הוא תנאי להכרזת אר\"ן?",["צורך לתעדף נפגעים כי אין מספיק כוחות","שני נפגעים קלים","נפגע אחד קשה","תאונה בלי נפגעים"],"אר\"ן מוגדר לפי פער בין נפגעים למשאבים."],["מה מדווח כונן ביציאה לאר\"ן?",["מספר כונן ו'בדרך לאר\"ן' בלבד","את כל פרטי האירוע","שאלות על מספר הנפגעים","את המיקום שלו בפירוט"],"שומרים על גל נקי."],["מי נמצא במעגל המענה הפנימי?",["המגיבים הראשונים בזירה","בתי החולים הרחוקים","משרד הבריאות","המשטרה בלבד"],"מעגל I."],["מי אחראי על סידור רכבי החירום בזירה?",["חניון 10","הצלה 10","פיקוד 10","הכונן הראשון"],"חניון 10 מטעם מד\"א."],["כמה מתנדבים יש באיחוד הצלה, לפי הנוהל?",["כ-8,000","כ-800","כ-80,000","כ-80"],"פרוסים בכל הארץ."]],"images":[["mci--5-01-p-031-126.webp","מיון בשטח: הערכה מהירה של כל נפגע"],["mci--5-01-p-031-128.webp","תנוחת התאוששות לנפגע מחוסר הכרה שנושם"],["mci--5-01-p-034-147.webp","כרטיס נפגע לאר\"ן עם סימון דחיפות בצבעים"],["mci--5-01-p-037-189.webp","חפ\"ק: מרכז שליטה ניידת באירוע"],["mci--5-01-p-030-121.webp","חוסם עורקים: הטיפול המציל העיקרי במיון"]]},"hazmat":{"learn":[{"h":"איפה פוגשים חומ\"ס","steps":false,"items":["תעשייה: אמוניה לקירור במפעלי מזון, חומצות ובסיסים, צבעים, ציפוי מתכות.","רפואה, חקלאות, מכוני מחקר ומעבדות.","תחבורה: מצברים, רכבים שמונעים בגז, ומשאיות ורכבות שמובילות חומ\"ס.","בבית ובנופש: כלור בבריכות, צוברי גז במסעדות, גז בישול, ממיסים."]},{"h":"חומרים דליקים","steps":false,"items":["שומרים מרחק בטוח של 200 מטר מאזור הבעירה, במיוחד כשיש אש.","עומדים בכיוון הנגדי לרוח (הרוח בגב), כדי לא לשאוף עשן.","מבקשים מהמוקד סיוע של כבאות.","נפגע שיוצא לכיוונך: קודם בטיחות, אחר כך הסרת בגדים וטיפול בכוויות."]}],"quiz":[["איזה מרחק בטוח שומרים מאזור בעירה של חומר דליק?",["200 מטר","20 מטר","5 מטר","אין צורך במרחק"],"וגם עומדים כשהרוח בגב."],["למה עומדים כשהרוח בגב באירוע חומ\"ס?",["כדי לא לשאוף עשן וגזים","כדי לראות טוב","כדי שיהיה חם","אין סיבה"],"הרוח מרחיקה את הענן מאיתנו."],["איפה עלולה להיות אמוניה?",["במערכות קירור של מפעלי מזון","בבריכות שחייה","בבתי מרקחת בלבד","במצברים"],"אמוניה משמשת לקירור תעשייתי."],["מה מופיע בשלט חומ\"ס על משאית?",["קוד חירום, מספר או\"ם וסימן הסיכון","שם הנהג","יעד הנסיעה","תאריך הייצור"],"המספרים מזהים את החומר ואת אופן הטיפול."]],"images":[["hazmat--5-02-p-016-099.webp","שלט חומ\"ס ברכב: קוד חירום, מספר או\"ם וסימן הסיכון"],["hazmat--5-02-p-017-107.webp","שלט לגז דחוס: 2T, או\"ם 1977"],["hazmat--5-02-p-024-139.webp","סימני הסיכון לפי סוגי החומרים"],["hazmat--5-02-p-014-089.webp","סיכון 1: חומרים נפיצים"],["hazmat--5-02-p-012-082.webp","סיכון 3: נוזלים דליקים"],["hazmat--5-02-p-017-103.webp","סיכון 8: חומרים מאכלים"],["hazmat--5-02-p-019-116.webp","סיכון 6: חומרים רעילים"],["hazmat--5-02-p-023-136.webp","מתח\"ב: מדריך תגובת חירום בחומ\"ס"],["hazmat--5-02-p-043-249.webp","ציוד מגן לצוות חומ\"ס"]]},"pregnancy-birth":{"learn":[{"h":"מה משתנה בגוף בהריון","steps":false,"items":["נשימה: קצב הנשימה עולה כדי לספק עוד חמצן, ונשים בהריון עלולות להרגיש קוצר נשימה.","לב וכלי דם: נפח הדם והדופק עולים, ובשליש השני לחץ הדם יורד מעט.","הרחם הכבד לוחץ על ורידים גדולים בשכיבה על הגב ומאט את חזרת הדם ללב, ולכן משכיבים על צד שמאל.","עיכול: הרחם דוחק את הקיבה והמעיים למעלה, יש צרבות ועצירות, וסכנת הקאה גבוהה יותר."]},{"h":"משך ההריון","steps":false,"items":["כ-40 שבועות מהיום הראשון של הווסת האחרונה; תאריך הלידה הוא הערכה בלבד.","שליש ראשון: עייפות, בחילות והקאות.","שליש שני: הבטן מתרחבת, ובסופו קצה הרחם מגיע ליד הצלעות.","שליש שלישי: הבשלת הריאות, כבדות וקוצר נשימה. אחרי שבוע 42 יש מעקב הריון עודף."]}],"quiz":[["למה משכיבים אישה בהריון מתקדם על צד שמאל?",["כדי שהרחם לא ילחץ על הווריד הגדול ויאט את חזרת הדם ללב","כדי שתירדם","כדי להקל על הנשימה בלבד","אין סיבה"],"שכיבה על הגב עלולה לגרום לירידת לחץ דם."],["כמה זמן נמשך הריון תקין?",["כ-40 שבועות","כ-30 שבועות","כ-50 שבועות","כ-20 שבועות"],"מהיום הראשון של הווסת האחרונה."],["למה אישה בהריון בסיכון גבוה יותר להקאה ושאיפה?",["הרחם דוחק את הקיבה והסוגר העליון רפוי","כי היא אוכלת יותר","כי יש לה חום","אין סיכון כזה"],"פרוגסטרון מרפה את הסוגר התחתון של הוושט."],["מה קורה לקצב הנשימה בהריון?",["עולה","יורד","לא משתנה","נעצר בלילה"],"צריכת החמצן גדלה."]],"images":[["pregnancy-birth--5-03-p-005-021.webp","מההפריה ועד ההשרשה ברחם"],["pregnancy-birth--5-03-p-010-040.webp","גובה הרחם לפי חודש ההריון"],["pregnancy-birth--5-03-p-016-072.webp","ההריון לפי שליש: חודשים 4-6"],["pregnancy-birth--5-03-p-020-097.webp","השליה וחבל הטבור"],["pregnancy-birth--5-03-p-027-126.webp","שלב א: צוואר הרחם נפתח, הראש יורד"],["pregnancy-birth--5-03-p-029-134.webp","שלב ב: לידת הראש"],["pregnancy-birth--5-03-p-030-138.webp","סיבוב ולידת הכתפיים"],["pregnancy-birth--5-03-p-031-144.webp","שלב ג: השליה מתנתקת"],["pregnancy-birth--5-03-p-031-145.webp","יציאת השליה והתכווצות הרחם"],["pregnancy-birth--5-03-p-039-170.webp","תמיכה בראש היילוד בזמן הלידה"],["pregnancy-birth--5-03-p-042-182.webp","קשירת חבל הטבור בשני מקומות"],["pregnancy-birth--5-03-p-045-193.webp","מדד אפגר: צבע, דופק, תגובה, טונוס ונשימה"]]},"birth-emerg":{"learn":[{"h":"מחלות שמחמירות בהריון","steps":false,"items":["כאב בטן שכיח בהריון, בדרך כלל ממתיחת הרצועות, אבל כל כאב בטן בהריון מפנים לבדיקת רופא.","סוכרת הריונית: העובר נוטה להיות גדול, מה שמקשה על הלידה, והיילוד עלול להתקשות לשמור על סוכר.","יתר לחץ דם בהריון מעלה סיכון לשבץ, לחסימת כלי דם ולפגיעה בשליה, ואי אפשר לתת את התרופות הרגילות."]},{"h":"דימום והפלה","steps":false,"items":["אי אפשר לדעת בשטח את מקור הדימום, ודימום לא תמיד אומר הפלה.","נוהגים ברגישות ונמנעים מלומר 'הפלה' ליד האישה.","בודקים סימני הלם, אוספים רקמות וקרישים ומעבירים לבית החולים.","עובר שיצא עדיין מחובר בחבל הטבור: שני תופסנים על החבל וחיתוך ביניהם."]},{"h":"רעלת הריון: מה עושים","steps":true,"items":["נותנים חמצן בריכוז גבוה.","מודדים לחץ דם בשכיבה.","מעמעמים אורות חזקים, כי אור יכול לעורר פרכוס.","שואלים על כאב בבטן העליונה, כאב ראש, הפרעות ראייה ושינוי בכמות השתן, ומפנים בדחיפות."]}],"quiz":[["אישה ברעלת הריון. למה מעמעמים אורות?",["כי אור חזק עלול לעורר פרכוס","כדי שתנוח","כדי לחסוך חשמל","אין סיבה"],"פרכוס (אקלמפסיה) מסכן את האם ואת העובר."],["אישה בהריון מדממת. אפשר לקבוע בשטח שזו הפלה?",["לא, אי אפשר לדעת את מקור הדימום","כן, תמיד","כן, לפי צבע הדם","כן, לפי הכאב"],"דימום לא מעיד בהכרח על הפלה."],["מה עושים עם רקמות שנפלטו בדימום בהריון?",["אוספים ומעבירים לבית החולים","זורקים","משאירים בבית","שוטפים"],"הצוות בבית החולים צריך לבדוק אותן."],["למה סוכרת הריונית מקשה על הלידה?",["כי העובר נוטה להיות גדול","כי הלידה מוקדמת תמיד","כי האם מתעלפת","היא לא מקשה"],"עובר גדול מגביר סיכון לפרע כתפיים."],["אישה בהריון עם כאב בטן. מה עושים?",["מפנים לבדיקת רופא","מרגיעים ומשחררים","נותנים משכך כאבים","מחכים יום"],"כל כאב בטן בהריון נבדק."]],"images":[["birth-emerg--5-04-p-012-040.webp","היפרדות שליה: דימום פנימי או חיצוני"],["birth-emerg--5-04-p-014-045.webp","שליית פתח: השליה מכסה את צוואר הרחם"],["birth-emerg--5-04-p-015-048.webp","הריון מחוץ לרחם, בחצוצרה"],["birth-emerg--5-04-p-018-058.webp","מצג עכוז"],["birth-emerg--5-04-p-020-068.webp","שכיבה רוחבית של העובר"],["birth-emerg--5-04-p-021-072.webp","צניחת חבל טבור: תנוחת ברכיים-חזה להורדת הלחץ"],["birth-emerg--5-04-p-022-076.webp","פרע כתפיים: הכתף נתקעת מאחורי עצם הערווה"],["birth-emerg--5-04-p-023-079.webp","הריון תאומים"],["birth-emerg--5-04-p-026-092.webp","חגורת בטיחות נכונה בהריון: מתחת לבטן"],["birth-emerg--5-04-p-033-118.webp","החייאת יילוד: עיסויים באגודלים"],["birth-emerg--5-04-p-035-131.webp","הנשמת יילוד באמבו"]]},"prevention":{"learn":[{"h":"עובדות על תזונה","steps":false,"items":["אכילה בערב לא משמינה בפני עצמה; מה שקובע הוא הכמות הכוללת והגיוון, גם למי שעובד במשמרות.","טוסט או צנים לא פחות קלוריים מלחם: רק המים יוצאים.","תפוח ירוק ותפוח אדום: אותה כמות סוכר וקלוריות.","דבש דומה בערכו התזונתי לסוכר חום ולבן.","פרי שלם עדיף על מיץ, ומים הם המשקה הטוב ביותר."]},{"h":"הרגלים","steps":false,"items":["לפחות 60 דקות פעילות גופנית כל יום לילדים, וההורים כדוגמה.","להגביל זמן מסך ולתכנן פעילויות בבית ומחוצה לו.","חטיפים בריאים במקום חטיפים עתירי סוכר ושומן.","להפחית אלכוהול, להפסיק לעשן ולהימנע מסמים, ולהיעזר באנשי מקצוע כשצריך."]}],"quiz":[["תפוח ירוק פחות מתוק ולכן פחות קלורי מתפוח אדום?",["לא, הם זהים בסוכר ובקלוריות","כן, בחצי","כן, ברבע","לתפוח ירוק אין סוכר"],"רק הטעם חמוץ יותר."],["דבש בריא יותר מסוכר?",["לא, ערכו התזונתי דומה לסוכר","כן, אין בו קלוריות","כן, הוא חלבון","כן, הוא ירק"],"מבחינה תזונתית הוא סוכר."],["מה המשקה הטוב ביותר להרוות צמא?",["מים","מיץ פירות","משקה ממותק","משקה אנרגיה"],"מיצים מכילים הרבה סוכר."]],"images":[]},"home-meds":{"learn":[{"h":"דרכי מתן נוספות","steps":false,"items":["PO דרך הפה, SL מתחת ללשון, IM לשריר, SC מתחת לעור.","IV לווריד, IO לתוך העצם, ET לתוך הטובוס.","PR דרך פי הטבעת, אינהלציה בשאיפה, ושימוש חיצוני (topical) בקרמים ומשחות."]},{"h":"שלושה שמות לכל תרופה","steps":false,"items":["שם כימי: תיאור המבנה המולקולרי, ארוך וקשה.","שם גנרי (בינלאומי): שם החומר הפעיל, למשל חומצה אצטילסליצילית.","שם מסחרי: שם המותג, למשל אספירין, מיקרופירין, טבפירין או קרטיה.","המינון נקבע לפי המצב, הגיל, המשקל והמחלה, ונמדד במ\"ג, במ\"ל, ביחידות, בכדורים או בלחיצות משאף."]}],"quiz":[["מה פירוש IO?",["הזרקה לתוך העצם","הזרקה לשריר","מתחת ללשון","דרך הפה"],"Intraosseous."],["מיקרופירין וקרטיה הם:",["שמות מסחריים של אספירין","שמות גנריים","תרופות לסוכרת","משאפים"],"החומר הפעיל: חומצה אצטילסליצילית."],["מה פירוש SC?",["הזרקה מתחת לעור","הזרקה לווריד","שאיפה","דרך פי הטבעת"],"Subcutaneous."],["לפי מה נקבע מינון של תרופה?",["מצב, גיל, משקל ומחלה","צבע הכדור","שעה ביום בלבד","מחיר התרופה"],"לפעמים לפי מ\"ג לק\"ג."]],"images":[["home-meds--5-06-p-007-023.webp","קריאת מרשם: פרטי החולה, תרופה, מינון ותאריך"],["home-meds--5-06-p-012-037.webp","פוסיד (פורוסמיד): משתן לאי-ספיקת לב"]]},"monitor":{"learn":[{"h":"איך נוצרים הגלים","steps":true,"items":["הגל החשמלי מתחיל ב-SA ומתפשט לשתי העליות: גל P.","ב-AV ההולכה מואטת (בזכות יוני סידן), וזה הקו השטוח אחרי P.","הגל עובר מהר בצרור היס ובסיבי פורקינייה לחדרים: מכלול QRS (יוני נתרן).","גל T: סוף ההתאוששות (רפולריזציה) של החדרים."]},{"h":"שלושה סוגי מכשירים","steps":false,"items":["דפיברילטור AED: קורא קצב מ-1-2 זוויות, מחליט לבד, ונותן טיפול אחד (שוק).","מוניטור: קורא מ-3 זוויות, וההחלטות בדרך כלל של המטפל.","אק\"ג 12 לידים: 12-18 זוויות, לא מחליט על טיפול, ומאבחן גם איסכמיה בשריר הלב.","הצבעים של הכבלים משתנים בין יצרנים; הכיתוב על הכבל הוא הקובע."]},{"h":"היסטוריה קצרה","steps":false,"items":["ב-1790 גלוואני הראה שחשמל מזיז רגלי צפרדע.","ב-1901 איינטהובן רשם לראשונה את גלי הלב, וקרא להם PQRST."]}],"quiz":[["מה גורם לקו השטוח אחרי גל P?",["האטת ההולכה ב-AV","התכווצות החדרים","דום לב","הפרעה במכשיר"],"העיכוב נותן לחדרים זמן להתמלא."],["כמה זוויות קורא אק\"ג 12 לידים?",["12-18","1-2","3","100"],"לכן הוא מאבחן איסכמיה."],["צבעי הכבלים במכשיר חדש שונים ממה שלמדת. לפי מה מחברים?",["לפי הכיתוב על הכבל","לפי הצבע שלמדת","לפי האורך","לא משנה"],"הצבעים משתנים מיצרן ליצרן."],["מי רשם לראשונה את גלי הלב?",["וילם איינטהובן, 1901","גלוואני, 1790","ניוטון","פסטר"],"הוא קרא להם PQRST."]],"images":[["monitor--5-07-p-004-027.webp","גלי האק\"ג: P, QRS, T ומרווחי PR, ST, QT"],["monitor--5-07-p-005-030.webp","מערכת ההולכה: SA, AV, צרור היס וסיבי פורקינייה"],["monitor--5-07-p-007-046.webp","גל T: התאוששות החדרים"],["monitor--5-07-p-013-071.webp","3 אלקטרודות: RA, LA, LL"],["monitor--5-07-p-014-074.webp","4 אלקטרודות לגפיים: RA, LA, RL, LL"],["monitor--5-07-p-016-081.webp","12 חיבורים: אלקטרודות גפיים ו-V1 עד V6"],["monitor--5-07-p-028-135.webp","קצב סינוס תקין לעומת ברדיקרדיה"]]},"team-lead":{"learn":[{"h":"צוות טוב","steps":false,"items":["לא תמיד אנשי הצוות מכירים זה את זה; מנהל הצוות צריך ללכד אותם.","כל אחד מכיר את תפקידו ואת נקודות הממשק עם האחרים, בלי לדרוך על התחום של אחרים.","גיוון בצוות משפר יצירתיות ולמידה הדדית.","מנהל שמטפל בקונפליקטים בחכמה מאפשר לצוות לשתף בקשיים ולמצוא פתרונות."]},{"h":"למה זה קשה בשטח","steps":false,"items":["סכנה לחיי המטופל, וצורך בהחלטות מהירות: טעות או עיכוב עולים ביוקר.","סיכון לצוות: דקירות מחט ומחלות מדבקות.","לחץ אצל המטופל ואצל הצוות, ולא תמיד יש תשובה נכונה אחת.","מנהל הצוות אחראי גם על תקינות הציוד ועל זיהוי פעולות לא יעילות."]}],"quiz":[["צוות שלא מכיר זה את זה. מה תפקיד המנהל?",["ללכד את הצוות ולהגדיר תפקידים","לעשות הכול לבד","לחכות שיתגבשו","לשלוח אותם הביתה"],"תפקידים ברורים משפרים ביצועים."],["מה היתרון של גיוון בצוות?",["יותר יצירתיות ולמידה הדדית","אין יתרון","פחות עבודה","מהירות נהיגה"],"אנשים שונים מביאים רעיונות שונים."],["על מה אחראי מנהל הצוות מלבד הטיפול?",["על תקינות הציוד ועל זיהוי פעולות לא יעילות","על תדלוק בלבד","על ניקיון הרחוב","על שום דבר נוסף"],"הוא רואה את התמונה הכוללת."]],"images":[]},"ambulance":{"learn":[{"h":"עוד מהנוהל","steps":false,"items":["כדי להיות נהג: לפחות 30 משמרות באמבולנס במסגרת ההכשרה, ואישור של ועדה של שלושה ראשי אגפים לפחות.","בתחילת משמרת: בודקים את הרכב מבחוץ ומבפנים ואת הציוד, משלימים חוסרים, ורק אז מדווחים למוקד על פתיחת משמרת.","כל תקלה ברכב מדווחים מיד למוקד ולאחראי האמבולנס האזורי.","עמידה בנהלים היא הגב החוקי והארגוני של הצוות."]},{"h":"העברת מטופל","steps":false,"items":["ראש הצוות מעביר במהירות ובבירור את מצב המטופל לצוות שמקבל.","בהעברה למלר\"ד מוסרים גם את טופס התיעוד, ושומרים עותק באמבולנס.","בתיעוד: תיאור מילולי של התלונה, הרקע, הממצאים והטיפולים שניתנו בפועל."]}],"quiz":[["מה עושים בתחילת משמרת לפני הדיווח למוקד?",["בודקים את הרכב ואת הציוד ומשלימים חוסרים","יוצאים מיד לנסיעה","מדווחים ורק אחר כך בודקים","לא עושים כלום"],"קודם תקינות, אחר כך פתיחת משמרת."],["התגלתה תקלה מכנית ברכב. מה עושים?",["מדווחים מיד למוקד ולאחראי האמבולנס","ממשיכים ונוהגים","מתקנים לבד בלי לדווח","מחכים לסוף המשמרת"],"בטיחות הצוות והמטופל."],["מי מעביר את מצב המטופל לצוות במיון?",["ראש הצוות","הנהג בלבד","המשפחה","אף אחד"],"העברה ברורה ומהירה."]],"images":[]}};
